import pg from "pg";
const { Client } = pg;

const HOST_POOLER = "ep-purple-heart-aop41ogj-pooler.c-2.ap-southeast-1.aws.neon.tech";
const HOST_DIRECT = "ep-purple-heart-aop41ogj.c-2.ap-southeast-1.aws.neon.tech";
const USER = "neondb_owner";
const PW = "[REDACTED]";
const DB = "neondb";
const ENDPOINT = "ep-purple-heart-aop41ogj";

async function tryConn(label, cfg) {
  const c = new Client(cfg);
  const t0 = Date.now();
  try {
    await c.connect();
    const r = await c.query("select 1 as ok");
    console.log(`[${label}] OK in ${Date.now() - t0}ms -> ${JSON.stringify(r.rows[0])}`);
    await c.end();
  } catch (e) {
    console.log(`[${label}] FAIL in ${Date.now() - t0}ms -> ${e.code || ""} ${e.message}`);
    try { await c.end(); } catch {}
  }
}

const base = { user: USER, password: PW, database: DB, port: 5432 };

// 1) Pooler with explicit SNI servername
await tryConn("pooler + SNI servername", {
  ...base, host: HOST_POOLER,
  ssl: { rejectUnauthorized: false, servername: HOST_POOLER },
});

// 2) Direct (non-pooler) endpoint
await tryConn("direct endpoint", {
  ...base, host: HOST_DIRECT,
  ssl: { rejectUnauthorized: false, servername: HOST_DIRECT },
});

// 3) Pooler, password carries endpoint hint (Neon SNI workaround)
await tryConn("pooler + endpoint-in-options", {
  ...base, host: HOST_POOLER,
  options: `endpoint=${ENDPOINT}`,
  ssl: { rejectUnauthorized: false, servername: HOST_POOLER },
});

