import net from "node:net";
import tls from "node:tls";

const HOST = "ep-purple-heart-aop41ogj-pooler.c-2.ap-southeast-1.aws.neon.tech";
const PORT = 5432;
const t0 = Date.now();
const ms = () => Date.now() - t0;

const sock = net.connect({ host: HOST, port: PORT, family: 4 });

sock.on("connect", () => {
  console.log(`[${ms()}ms] TCP connected (IPv4). Sending Postgres SSLRequest...`);
  // SSLRequest packet: int32 length=8, int32 code=80877103
  const buf = Buffer.alloc(8);
  buf.writeInt32BE(8, 0);
  buf.writeInt32BE(80877103, 4);
  sock.write(buf);
});

sock.once("data", (d) => {
  const reply = d.toString("latin1", 0, 1);
  console.log(`[${ms()}ms] Server replied to SSLRequest: '${reply}' (S=TLS supported, N=no)`);
  if (reply === "S") {
    console.log(`[${ms()}ms] Upgrading to TLS...`);
    const tlsSock = tls.connect({ socket: sock, servername: HOST, rejectUnauthorized: false }, () => {
      console.log(`[${ms()}ms] ✅ TLS HANDSHAKE OK — cipher ${tlsSock.getCipher()?.name}. Network path is FINE.`);
      tlsSock.destroy();
      process.exit(0);
    });
    tlsSock.on("error", (e) => console.log(`[${ms()}ms] ❌ TLS error: ${e.code || ""} ${e.message}`));
  }
});

sock.on("error", (e) => console.log(`[${ms()}ms] ❌ socket error: ${e.code || ""} ${e.message}`));
sock.on("close", (hadErr) => console.log(`[${ms()}ms] socket closed (hadError=${hadErr})`));
setTimeout(() => { console.log(`[${ms()}ms] hard timeout, giving up`); process.exit(1); }, 30000);

