1	import { useEffect, useState, useCallback } from "react";
2	import QRCode from "qrcode";
3	import { RefreshCw, Printer, Star } from "lucide-react";
4	import { getBadges } from "../lib/claudeParse.js";
5	import { useLang } from "../lib/i18n.jsx";
6	
7	/**
8	 * Boarding passes — one scannable QR badge per delegate (Vance).
9	 * The document reader onboards delegates; each gets a unique qr_code, shown here
10	 * as a printable badge. The on-site scanner reads it to board them.
11	 */
12	const STATUS_CLS = { PRESENT: "badge-present", MISSING: "badge-review", UNASSIGNED: "badge-muted" };
13	
14	export default function BoardingPassesView({ tripId }) {
15	  const { t } = useLang();
16	  const [data, setData] = useState({ delegates: [], coaches: [], total: 0, present: 0 });
17	  const [qr, setQr] = useState({}); // delegateId -> data URL
18	  const [loading, setLoading] = useState(true);
19	
20	  const load = useCallback(async () => {
21	    setLoading(true);
22	    try {
23	      const res = await getBadges(tripId || "t-1");
24	      setData(res);
25	      const entries = await Promise.all(
26	        res.delegates.map(async (d) => [d.id, d.qr_code ? await QRCode.toDataURL(d.qr_code, { width: 150, margin: 1 }) : null])
27	      );
28	      setQr(Object.fromEntries(entries));
29	    } catch { /* ignore */ } finally { setLoading(false); }
30	  }, [tripId]);
31	
32	  useEffect(() => { load(); }, [load]);
33	
34	  const coachName = (id) => {
35	    const c = data.coaches.find((x) => x.id === id);
36	    return c ? `${c.name}${c.city ? ` · ${c.city}` : ""}` : t("Unassigned");
37	  };
38	
39	  return (
40	    <div>
41	      <div className="row between" style={{ marginBottom: 16, flexWrap: "wrap", gap: 10 }}>
42	        <div>
43	          <h2 style={{ fontSize: 16 }}>{t("Boarding passes")}</h2>
44	          <p className="muted" style={{ fontSize: 13, marginTop: 2 }}>
45	            {t("A unique QR badge for each delegate. Print them, or show on a phone for the scanner.")}
46	          </p>
47	        </div>
48	        <div className="row" style={{ gap: 10 }}>
49	          <button className="btn btn-ghost" onClick={load}><RefreshCw size={15} /> {t("Refresh")}</button>
50	          <button className="btn btn-primary" onClick={() => window.print()}><Printer size={15} /> {t("Print all")}</button>
51	        </div>
52	      </div>
53	
54	      {loading && <div className="muted" style={{ fontSize: 13 }}>{t("Generating passes…")}</div>}
55	      {!loading && data.delegates.length === 0 && (
56	        <div className="muted" style={{ fontSize: 13 }}>{t("No delegates for this trip yet. Onboard some first.")}</div>
57	      )}
58	
59	      <div className="mg-pass-grid" style={{ display: "grid", gridTemplateColumns: "repeat(auto-fill, minmax(220px, 1fr))", gap: 14 }}>
60	        {data.delegates.map((d) => (
