1	/* =============================================================================
2	 *  OWNED BY:  Jayden — Exception Logging, Critical Alerts & QR check-in
3	 *
4	 *  A SELF-CONTAINED live QR scanner, dropped into the "QR" slot of the shared
5	 *  check-in screen (QRCheckInPage.jsx). It is deliberately isolated:
6	 *
7	 *   - It opens and closes its OWN camera stream, and is only ever mounted while
8	 *     scanMode === "qr", so it never runs at the same time as Vimal's face
9	 *     camera. Nothing in his face / voice / low-light pipeline is touched.
10	 *   - It decodes with jsQR on an off-DOM canvas (no frame is persisted).
11	 *   - A valid MusterGo delegate badge is registered through Jayden's own
12	 *     backend route POST /api/checkins/qr (method = 'QR'); the delegate flips
13	 *     to PRESENT so JQ's dashboard head-count and the reverse-headcount agree.
14	 *   - Styling uses ONLY tokens.css variables; the one <style> block is
15	 *     namespaced `jayden-*` so it can't collide with Vimal's `vimal-*` rules.
16	 *
17	 *  BADGE FORMAT (what the two generated QR codes encode):
18	 *    {"sys":"MUSTERGO","v":1,"typ":"DELEGATE_BADGE",
19	 *     "tripId":"t-1","delegateId":"d-1","name":"Lim Wei Jie","sig":"…"}
20	 *  Anything that is not this shape → "QR code invalid".
21	 * ============================================================================= */
22	
23	import { useEffect, useRef, useState, useCallback } from "react";
24	import jsQR from "jsqr";
25	import { QrCode, CheckCircle2, AlertTriangle, Keyboard, RotateCcw } from "lucide-react";
26	import { checkInByQR } from "../lib/exceptionsApi.js";
27	
28	const RESULT_MS = 3200;          // how long a result card stays up
29	const RESCAN_COOLDOWN_MS = 3500; // ignore the same code re-appearing this soon
30	const SCAN_INTERVAL_MS = 200;    // decode cadence
31	
32	/* Validate a decoded string as a MusterGo delegate badge. Pure + exported so
33	 * it can be unit-tested independently of the camera. */
34	export function parseBadge(raw) {
35	  if (typeof raw !== "string" || !raw.trim()) return { ok: false };
36	  let data;
37	  try { data = JSON.parse(raw.trim()); } catch { return { ok: false }; }
38	  if (!data || typeof data !== "object") return { ok: false };
39	  if (data.sys !== "MUSTERGO" || data.typ !== "DELEGATE_BADGE") return { ok: false };
40	  if (typeof data.tripId !== "string" || !data.tripId) return { ok: false };
41	  if (typeof data.delegateId !== "string" || !data.delegateId) return { ok: false };
42	  return {
43	    ok: true,
44	    tripId: data.tripId,
45	    delegateId: data.delegateId,
46	    name: typeof data.name === "string" ? data.name : null,
47	  };
48	}
49	
50	/* Short confirmation / error tone via Web Audio — mirrors the scanner's audio
51	 * feedback without importing any of Vimal's helpers. */
52	function playTone(ok) {
53	  try {
54	    const Ctx = window.AudioContext || window.webkitAudioContext;
55	    const ctx = new Ctx();
56	    const osc = ctx.createOscillator();
57	    const gain = ctx.createGain();
58	    osc.type = ok ? "sine" : "square";
59	    osc.frequency.value = ok ? 880 : 220;
60	    gain.gain.value = 0.12;
61	    osc.connect(gain).connect(ctx.destination);
62	    osc.start();
63	    osc.stop(ctx.currentTime + (ok ? 0.16 : 0.4));
64	    osc.onended = () => ctx.close();
65	  } catch { /* no audio device — the on-screen card still shows */ }
66	}
67	
68	const JAYDEN_CSS = `
69	@keyframes jayden-scan { 0% { top: 12%; } 50% { top: 84%; } 100% { top: 12%; } }
70	.jayden-scan {
71	  position: absolute; left: 12%; right: 12%; height: 2px;
72	  background: var(--st-present); opacity: .9; border-radius: 2px;
73	  box-shadow: 0 0 12px var(--st-present);
74	  animation: jayden-scan 1.8s ease-in-out infinite;
75	}
76	.jayden-corner { position: absolute; width: 30px; height: 30px; border: 3px solid var(--surface); opacity: .92; }
77	.jayden-corner.tl { top: 14px; left: 14px; border-right: none; border-bottom: none; border-radius: 10px 0 0 0; }
78	.jayden-corner.tr { top: 14px; right: 14px; border-left: none; border-bottom: none; border-radius: 0 10px 0 0; }
79	.jayden-corner.bl { bottom: 14px; left: 14px; border-right: none; border-top: none; border-radius: 0 0 0 10px; }
80	.jayden-corner.br { bottom: 14px; right: 14px; border-left: none; border-top: none; border-radius: 0 0 10px 0; }
81	@keyframes jayden-pop { from { transform: scale(.92); opacity: 0; } to { transform: scale(1); opacity: 1; } }
82	.jayden-pop { animation: jayden-pop .18s ease-out; }
83	@media (prefers-reduced-motion: reduce) {
84	  .jayden-scan { animation: none; top: 48%; }
85	  .jayden-pop { animation: none; }
86	}
87	`;
88	
89	export default function QRScannerPanel({ tripId, coachId, coachLabel, onCheckedIn }) {
90	  const [camState, setCamState] = useState("starting"); // starting | live | error
91	  const [result, setResult] = useState(null);           // { kind, title, sub }
92	  const [submitting, setSubmitting] = useState(false);
93	  const [showManual, setShowManual] = useState(false);
94	  const [manualText, setManualText] = useState("");
95	
96	  const videoRef = useRef(null);
97	  const streamRef = useRef(null);
98	  const canvasRef = useRef(null);
99	  const loopRef = useRef(null);
100	  const resultTimerRef = useRef(null);
101	  const lastScanRef = useRef({ value: "", at: 0 });
102	  const busyRef = useRef(false); // guards against overlapping submits
103	
104	  const clearResultSoon = useCallback(() => {
105	    clearTimeout(resultTimerRef.current);
106	    resultTimerRef.current = setTimeout(() => setResult(null), RESULT_MS);
107	  }, []);
108	
109	  /* Register a valid badge, or surface a clear failure. */
110	  const register = useCallback(async (badge) => {
111	    if (busyRef.current) return;
112	    busyRef.current = true;
113	    setSubmitting(true);
114	    try {
115	      const res = await checkInByQR({ tripId, delegateId: badge.delegateId, coachId });
116	      playTone(true);
117	      setResult({
118	        kind: "success",
119	        title: "Attendance registered",
120	        sub: `${res.name || badge.name || badge.delegateId}${res.duplicate ? " · already checked in" : " · marked present"}`,
121	      });
122	      onCheckedIn?.();
123	    } catch (e) {
124	      playTone(false);
125	      const msg =
126	        e.status === 404 ? "Badge not recognised on this trip."
127	        : e.status === 401 ? "Session expired — sign in again."
128	        : e.message || "Check-in failed — retry, or use Manual.";
129	      setResult({ kind: "error", title: "Check-in failed", sub: msg });
130	    } finally {
131	      setSubmitting(false);
132	      busyRef.current = false;
133	      clearResultSoon();
134	    }
135	  }, [tripId, coachId, onCheckedIn, clearResultSoon]);
136	
137	  /* Route any decoded / typed string through validation. */
138	  const handleDecoded = useCallback((raw) => {
139	    const now = Date.now();
140	    if (raw === lastScanRef.current.value && now - lastScanRef.current.at < RESCAN_COOLDOWN_MS) return;
141	    lastScanRef.current = { value: raw, at: now };
142	
143	    const badge = parseBadge(raw);
144	    if (!badge.ok) {
145	      playTone(false);
146	      // Log the exact bytes jsQR handed us — invaluable if a real badge is
147	      // ever mis-scanned (partial read, wrong QR, stale code, etc.).
148	      console.debug("[QRScannerPanel] rejected scan:", JSON.stringify(raw));
149	      const preview = raw.length > 60 ? `${raw.slice(0, 60)}…` : raw;
150	      setResult({
151	        kind: "error",
152	        title: "QR code invalid",
153	        sub: `Not a MusterGo delegate badge. Read: "${preview}"`,
154	      });
155	      clearResultSoon();
156	      return;
157	    }
158	    register(badge);
159	  }, [register, clearResultSoon]);
160	
161	  /* Camera + decode loop. Runs only while this component is mounted (i.e. only
162	   * in QR mode), and fully tears down on unmount. */
163	  useEffect(() => {
164	    let cancelled = false;
165	
166	    async function start() {
167	      try {
168	        const stream = await navigator.mediaDevices.getUserMedia({
169	          video: { facingMode: { ideal: "environment" } }, audio: false,
170	        });
171	        if (cancelled) { stream.getTracks().forEach((t) => t.stop()); return; }
172	        streamRef.current = stream;
173	        if (videoRef.current) {
174	          videoRef.current.srcObject = stream;
175	          await videoRef.current.play().catch(() => {});
176	        }
177	        setCamState("live");
178	        tick();
179	      } catch {
180	        if (!cancelled) { setCamState("error"); setShowManual(true); }
181	      }
182	    }
183	
184	    function tick() {
185	      loopRef.current = setInterval(() => {
186	        if (busyRef.current || result) return; // pause while a result card is up
187	        const video = videoRef.current;
188	        if (!video || !video.videoWidth) return;
189	        const canvas = canvasRef.current || (canvasRef.current = document.createElement("canvas"));
