/**
 * Build an Error from a failed response, carrying the backend's message and
 * error code so the UI can show something specific (e.g. a weak-password
 * message) instead of just a status number.
 */
async function toError(res, method, path) {
  let body = {};
  try {
    body = await res.json();
  } catch { /* no/invalid JSON body */ }
  const err = new Error(body.message || `${method} ${path} failed (${res.status})`);
  err.status = res.status;
  err.code = body.error; // e.g. "WEAK_PASSWORD", "USERNAME_TAKEN"
  return err;
}

/* ---- Requests ----------------------------------------------------------- */
export async function apiGet(path) {
  const res = await fetch(`${BASE_URL}${path}`, { headers: { ...authHeader() } });
  if (!res.ok) throw await toError(res, "GET", path);
  return res.json();
}

