(async () => {
  const m = await import('/src/components/QRScannerPanel.jsx');
  const { parseBadge } = m;
  const cases = [
    ["Vance boarding pass (real)", "MG-B87558CB"],
    ["Vance pass, lowercase typed", "mg-b87558cb"],
    ["Vance pass, whitespace", "  MG-F47B8F81  "],
    ["MUSTERGO JSON badge", '{"sys":"MUSTERGO","v":1,"typ":"DELEGATE_BADGE","tripId":"t-1","delegateId":"d-1","name":"Lim Wei Jie","sig":"7F3A9C2E"}'],
    ["invalid test payload", "NOT-A-BADGE::sc-cci-visitor-pass::9931"],
    ["random URL", "https://example.com"],
    ["near-miss: wrong length", "MG-12345"],
    ["near-miss: non-hex", "MG-ZZZZZZZZ"],
    ["empty", "   "],
  ];
  return cases.map(([label, input]) => {
    const r = parseBadge(input);
    return `${r.ok ? "ACCEPT" : "reject"}  ${r.ok ? "kind=" + r.kind + (r.code ? " code=" + r.code : " delegateId=" + r.delegateId) : "—"}   <- ${label}`;
  }).join("\n");
})()

