API=https://localhost:5173/api
TOKEN=$(node -e "console.log(require(process.env.TEMP+'/jq_login.json').token)")
for ep in "/trips" "/trips/t-1/dashboard" "/trips/t-1/delegates"; do
  code=$(curl -sk "$API$ep" -H "Authorization: Bearer $TOKEN" -o "$TEMP/r.json" -w "%{http_code}")
  echo "  $ep -> HTTP $code"
done
echo "=== delegates visible ==="
curl -sk "$API/trips/t-1/delegates" -H "Authorization: Bearer $TOKEN" | node -e "
let d='';process.stdin.on('data',c=>d+=c).on('end',()=>{try{const r=JSON.parse(d);const list=r.delegates||r;
console.log('  count:',Array.isArray(list)?list.length:'n/a');
(Array.isArray(list)?list:[]).slice(0,3).forEach(x=>console.log('   -',x.name,'|',x.status));
}catch(e){console.log('  ',d.slice(0,160))}})"

