/* =============================================================================
 *  OWNED BY:  Jayden — Exception Logging & QR Fallback
 *  Scoped to the exception inbox. Extends tokens.css; adds no global rules.
 * ============================================================================= */

.exc-header { display: flex; align-items: flex-start; justify-content: space-between; gap: 16px; flex-wrap: wrap; }

.exc-live {
  display: inline-flex; align-items: center; gap: 7px;
  font-size: 12px; font-weight: 600; color: var(--st-present);
  background: var(--st-present-bg); padding: 5px 11px; border-radius: 999px;
}
.exc-live.off { color: var(--ink-3); background: var(--st-neutral-bg); }
.exc-live .dot { width: 7px; height: 7px; border-radius: 50%; background: currentColor; animation: excPulse 1.6s ease-in-out infinite; }
@keyframes excPulse { 0%, 100% { opacity: 1; } 50% { opacity: 0.25; } }

/* ---- Critical banner ---------------------------------------------------- */
.exc-banner {
  display: flex; align-items: center; justify-content: space-between; gap: 16px;
  padding: 16px 20px; margin: 20px 0;
  background: var(--scc-red-tint); border: 1px solid var(--scc-red-tint-2);
  border-left: 4px solid var(--scc-red); border-radius: var(--r-lg);
}
.exc-banner__title { font-weight: 700; color: var(--scc-red-700); }
.exc-banner__sub { color: var(--scc-red-700); font-size: 14px; }

/* ---- Toolbar ------------------------------------------------------------ */
.exc-toolbar { display: flex; align-items: center; justify-content: space-between; gap: 12px; margin-bottom: 18px; flex-wrap: wrap; }
.exc-tabs { display: flex; gap: 10px; flex-wrap: wrap; }
.exc-tab {
  border: 1px solid var(--line); background: #fff; color: var(--ink-2);
  border-radius: 999px; padding: 8px 16px; font-size: 14px; font-weight: 600;
}
.exc-tab:hover { background: var(--surface-2); }
.exc-tab.active { background: var(--ink); color: #fff; border-color: var(--ink); }
.exc-tab .count { opacity: 0.7; font-variant-numeric: tabular-nums; }

/* ---- Row actions -------------------------------------------------------- */
.exc-actions { display: flex; gap: 8px; justify-content: flex-end; }
.exc-btn-sm {
  font-size: 13px; padding: 6px 12px; border-radius: var(--r-sm);
  border: 1px solid var(--line); background: #fff; font-weight: 600; color: var(--ink-2);
}
.exc-btn-sm:hover { background: var(--surface-2); }
.exc-btn-sm.resolve { color: var(--st-present); border-color: var(--st-present-bg); }
.exc-btn-sm.danger  { color: var(--scc-red); border-color: var(--scc-red-tint-2); }

.exc-issue-title { font-weight: 600; }
.exc-issue-sub { color: var(--ink-3); font-size: 12px; }
.exc-vip { font-size: 10px; font-weight: 700; color: var(--scc-red); background: var(--scc-red-tint); padding: 1px 6px; border-radius: 6px; margin-left: 6px; }

/* ---- States ------------------------------------------------------------- */
.exc-state { text-align: center; padding: 44px 24px; color: var(--ink-3); }
.exc-skeleton {
  height: 52px; border-radius: var(--r-sm); margin: 8px 0;
  background: linear-gradient(90deg, var(--line-2) 25%, var(--surface-2) 37%, var(--line-2) 63%);
  background-size: 400% 100%; animation: excShimmer 1.4s ease infinite;
}
@keyframes excShimmer { 0% { background-position: 100% 0; } 100% { background-position: 0 0; } }

.exc-toast {
  position: fixed; bottom: 24px; left: 50%; transform: translateX(-50%);
  background: var(--ink); color: #fff; padding: 12px 20px; border-radius: 999px;
  font-size: 14px; font-weight: 500; box-shadow: var(--shadow-lg); z-index: 60;
}

/* ---- Modal -------------------------------------------------------------- */
.exc-overlay { position: fixed; inset: 0; background: rgba(16, 24, 40, 0.45); display: grid; place-items: center; z-index: 50; padding: 20px; }
.exc-modal {
  width: 100%; max-width: 460px; background: var(--surface);
  border-radius: var(--r-lg); box-shadow: var(--shadow-lg); overflow: hidden;
  max-height: 92vh; display: flex; flex-direction: column;
}
.exc-modal__head { display: flex; align-items: center; justify-content: space-between; padding: 20px 22px 8px; }
.exc-modal__head h2 { font-size: 20px; }
.exc-modal__body { padding: 8px 22px 22px; overflow-y: auto; }
.exc-modal__x { border: none; background: none; color: var(--ink-3); padding: 4px; border-radius: var(--r-sm); }
.exc-modal__x:hover { background: var(--surface-2); }

.exc-issue-grid { display: grid; grid-template-columns: 1fr 1fr; gap: 10px; margin-bottom: 18px; }
.exc-issue-opt {
  display: flex; flex-direction: column; align-items: center; gap: 6px;
  padding: 14px 8px; border: 1px solid var(--line); border-radius: var(--r-md);
  background: #fff; font-size: 13px; font-weight: 600; color: var(--ink-2);
}
.exc-issue-opt:hover { border-color: var(--ink-3); }
.exc-issue-opt.selected { border-color: var(--scc-red); background: var(--scc-red-tint); color: var(--scc-red-700); }

.exc-textarea { resize: vertical; min-height: 64px; }

/* ---- "Others" free-text issue label ------------------------------------- */
.exc-other-wrap { margin: -8px 0 18px; }
.exc-other-row { display: flex; align-items: center; gap: 10px; }
.exc-other-row .input { flex: 1; }
.exc-other-count {
  font-size: 12px; font-weight: 600; color: var(--ink-3);
  font-variant-numeric: tabular-nums; flex-shrink: 0; min-width: 42px; text-align: right;
}
.exc-other-count.at-limit { color: var(--scc-red); }

/* ---- Priority selector (under the Critical toggle) ---------------------- */
.exc-prio-label {
  font-size: 12px; font-weight: 600; color: var(--ink-3);
  margin: 0 0 8px; display: block;
}
.exc-prio-row { display: flex; gap: 8px; }
.exc-prio-btn {
  flex: 1; display: inline-flex; align-items: center; justify-content: center; gap: 7px;
  padding: 9px 12px; border-radius: var(--r-sm); font-size: 13.5px; font-weight: 600;
  border: 1.5px solid var(--line); background: #fff; color: var(--ink-2);
  transition: background 0.12s, border-color 0.12s, color 0.12s;
}
.exc-prio-btn:hover:not(:disabled) { border-color: var(--ink-3); }
.exc-prio-btn .dot { width: 8px; height: 8px; border-radius: 50%; background: currentColor; flex-shrink: 0; }
.exc-prio-btn:disabled { opacity: 0.45; cursor: not-allowed; }

/* Selected states pull straight from the five-state palette, so a Normal
   button matches the violet "Normal" pill in the inbox, and Low matches slate. */
.exc-prio-btn[data-p="NORMAL"].selected {
  color: var(--st-normal); background: var(--st-normal-bg); border-color: var(--st-normal);
}
.exc-prio-btn[data-p="LOW"].selected {
  color: var(--st-neutral); background: var(--st-neutral-bg); border-color: var(--st-neutral);
}

/* When Critical is on it overrides the choice — show the row as superseded. */
.exc-prio-row.superseded { opacity: 0.5; }

.exc-critical {
  display: flex; align-items: center; gap: 12px; padding: 12px 14px;
  border: 1px solid var(--scc-red-tint-2); background: var(--scc-red-tint);
  border-radius: var(--r-md); margin: 16px 0; cursor: pointer;
}
.exc-critical__title { font-weight: 700; color: var(--scc-red-700); }
.exc-critical__sub { font-size: 13px; color: var(--scc-red-700); }
.exc-switch { width: 40px; height: 24px; border-radius: 999px; background: var(--line); position: relative; flex-shrink: 0; transition: background 0.15s; }
.exc-switch.on { background: var(--scc-red); }
.exc-switch .knob { position: absolute; top: 3px; left: 3px; width: 18px; height: 18px; border-radius: 50%; background: #fff; transition: transform 0.15s; }
.exc-switch.on .knob { transform: translateX(16px); }

.exc-error { color: var(--scc-red); font-size: 13px; margin-bottom: 8px; }

/* ---- Focus ring --------------------------------------------------------- */
.exc-tab:focus-visible, .exc-btn-sm:focus-visible,
.exc-issue-opt:focus-visible, .exc-modal__x:focus-visible,
.exc-critical:focus-visible { outline: 2px solid var(--scc-red); outline-offset: 2px; }

/* ---- Mobile: table becomes cards ---------------------------------------- */
.exc-cards { display: none; }

@media (max-width: 820px) {
  .exc-table-wrap { display: none; }
  .exc-cards { display: block; }
  .exc-toolbar { flex-direction: column; align-items: stretch; }
  .exc-toolbar .btn-primary { width: 100%; }
  .exc-tabs { overflow-x: auto; flex-wrap: nowrap; padding-bottom: 4px; -webkit-overflow-scrolling: touch; }
  .exc-tab { white-space: nowrap; }
  .exc-banner { flex-direction: column; align-items: flex-start; }
  .exc-banner .btn { width: 100%; }

  .exc-card { padding: 14px 16px; border-bottom: 1px solid var(--line-2); }
  .exc-card:last-child { border-bottom: none; }
  .exc-card__top { display: flex; align-items: center; justify-content: space-between; gap: 8px; margin-bottom: 8px; }
  .exc-card__meta { color: var(--ink-3); font-size: 13px; margin: 2px 0; }
  .exc-card .exc-actions { margin-top: 12px; }
  .exc-card .exc-btn-sm { flex: 1; text-align: center; }

  .exc-overlay { align-items: flex-end; padding: 0; }
  .exc-modal { max-width: 100%; border-radius: var(--r-lg) var(--r-lg) 0 0; max-height: 94vh; }
}

@media (prefers-reduced-motion: reduce) {
  .exc-live .dot, .exc-skeleton { animation: none; }
  .exc-switch, .exc-switch .knob { transition: none; }
}

