/* =============================================================================
 *  OWNED BY:  Jayden — Exception Logging & QR Fallback
 *
 *  Thin data layer for Screen 5. It deliberately builds on the team's shared
 *  lib/api.js (apiGet/apiPost/apiPatch/apiDelete) rather than calling fetch()
 *  directly, so it inherits the shared token storage, the "keep me signed in"
 *  behaviour, and the typed error objects (err.status / err.code) for free.
 *
 *  Endpoint paths follow HIGH_LEVEL_DESIGN.md §3.6.
 * ============================================================================= */

import { apiGet, apiPost, apiPatch, apiDelete, getToken } from "./api.js";

/** The base build ships a single trip (see data.js TRIP). */
export const TRIP_ID = "t-1";

/** Human labels for the exception_type enum. */
export const ISSUE_LABEL = {
  MISSING_PERSON: "Missing person",
  LOST_BADGE: "Lost badge",
  FACE_MATCH_FAILED: "Face match failed",
  DEAD_PHONE: "Dead phone",
  VIP_REQUEST: "VIP request",
  OTHER: "Other",
};

/**
 * Max characters for the free-text label on the "Others" issue type.
 * Mirrors TYPE_OTHER_MAX in backend/routes/exceptions.js and the
 * exception_tickets.type_other column width. Change all three together.
 */
export const TYPE_OTHER_MAX = 20;

/**
 * Selectable priorities, in the order the buttons appear.
 * `cls` maps onto the badge classes already in tokens.css, so the colours match
 * the pills used in the inbox: CRITICAL red, NORMAL violet, LOW slate.
 */
export const PRIORITIES = [
  { value: "CRITICAL", label: "Critical", cls: "badge-missing", colour: "var(--st-missing)", bg: "var(--st-missing-bg)" },
  { value: "NORMAL",   label: "Normal",   cls: "badge-normal",  colour: "var(--st-normal)",  bg: "var(--st-normal-bg)" },
  { value: "LOW",      label: "Low",      cls: "badge-neutral", colour: "var(--st-neutral)", bg: "var(--st-neutral-bg)" },
];

/** The two non-critical options, for the buttons under the Critical toggle. */
export const BASE_PRIORITIES = PRIORITIES.filter((p) => p.value !== "CRITICAL");

/**
 * Display label for a ticket's issue type.
 * A type='OTHER' ticket carries its own free-text label in `typeOther`; show
 * that rather than the generic word "Other".
 */
export function issueLabel(ticket) {
  if (!ticket) return "";
  if (ticket.type === "OTHER" && ticket.typeOther) return ticket.typeOther;
  return ISSUE_LABEL[ticket.type] || ticket.type;
}

/**
 * List tickets for the active trip.
 * @param {{status?: string, priority?: string}} filter
 * @returns {Promise<{tickets: Array, counts: {all:number,critical:number,open:number,resolved:number}}>}
 */
export async function listExceptions(filter = {}) {
  const qs = new URLSearchParams();
  if (filter.status) qs.set("status", filter.status);
  if (filter.priority) qs.set("priority", filter.priority);
  const suffix = qs.toString() ? `?${qs}` : "";
  return apiGet(`/trips/${TRIP_ID}/exceptions${suffix}`);
}

/**
 * Number of UNRESOLVED CRITICAL tickets — drives the sidebar badge.
 * Cheap: the server returns a single integer, not the ticket list.
 */
export async function getCriticalOpenCount() {
  const data = await apiGet(`/trips/${TRIP_ID}/exceptions/critical-count`);
  return data.criticalOpen ?? 0;
}

/** Delegates for the picker. Reads JQ's existing delegate endpoint. */
export async function getDelegates() {
  const data = await apiGet(`/trips/${TRIP_ID}/delegates`);
  return data.delegates || [];
}

/** Coaches (from the shared dashboard view), keyed id → "Coach 2". */
export async function getCoaches() {
  const data = await apiGet(`/trips/${TRIP_ID}/dashboard`);
  return data.coaches || [];
}

/**
 * Raise a ticket. `markCritical` maps to priority CRITICAL, which the server
 * pushes to every connected staff device.
 */
/**
 * Raise a ticket.
 *
 * @param {object}  o
 * @param {string}  o.type          one of the exception_type enum values
 * @param {string} [o.typeOther]    free-text label, required when type === 'OTHER'
 * @param {string} [o.priority]     'CRITICAL' | 'NORMAL' | 'LOW'
 * @param {boolean}[o.markCritical] legacy shorthand — forces CRITICAL
 *
 * `markCritical` is honoured for backwards compatibility and always wins, since
 * the Critical toggle is the escalation switch. Otherwise the explicit
 * `priority` is used, defaulting to NORMAL.
 */
export async function createException({ type, typeOther, delegateId, coachId, note, priority, markCritical }) {
  const finalPriority = markCritical
    ? "CRITICAL"
    : (["CRITICAL", "NORMAL", "LOW"].includes(priority) ? priority : "NORMAL");

  return apiPost(`/trips/${TRIP_ID}/exceptions`, {
    type,
    typeOther: type === "OTHER" ? (typeOther || "").trim().slice(0, TYPE_OTHER_MAX) : null,
    delegateId: delegateId || null,
    coachId: coachId || null,
    note: note || null,
    priority: finalPriority,
    clientEventId: crypto.randomUUID(), // idempotency key (offline outbox)
  });
}

/** Resolve a ticket. Throws err.code === 'ALREADY_RESOLVED' (409) on a race. */
export async function resolveException(id) {
  return apiPatch(`/exceptions/${id}`, { status: "RESOLVED" });
}

/** Change a ticket's priority while it's still open. */
export async function updatePriority(id, priority) {
  return apiPatch(`/exceptions/${id}`, { priority });
}

/** Delete a ticket raised in error. */
export async function deleteException(id) {
  return apiDelete(`/exceptions/${id}`);
}

/** Manual attendance override — count a delegate present without a scan. */
export async function manualOverride(delegateId) {
  return apiPost(`/checkins/manual`, {
    tripId: TRIP_ID,
    delegateId,
    clientEventId: crypto.randomUUID(),
    clientTs: new Date().toISOString(),
  });
}

/**
 * QR badge check-in — count a delegate present from a scanned delegate badge.
 * Writes a method='QR' row to check_in_logs and flips the delegate to PRESENT,
 * so JQ's dashboard head-count updates live. Returns { delegateId, name,
 * status, method, duplicate }.
 */
export async function checkInByQR({ tripId = TRIP_ID, delegateId, coachId = null }) {
  return apiPost(`/checkins/qr`, {
    tripId,
    delegateId,
    coachId,
    clientEventId: crypto.randomUUID(),
    clientTs: new Date().toISOString(),
  });
}

/**
 * Subscribe to live ticket events (Server-Sent Events).
 * EventSource cannot send an Authorization header, so the token goes in the
 * query string; the server accepts either.
 * @returns {() => void} unsubscribe
 */
export function subscribeStream(onEvent) {
  const base = import.meta.env.VITE_API_URL || "/api";
  const token = getToken();
  if (!token) return () => {};

  const es = new EventSource(`${base}/exceptions/stream?token=${encodeURIComponent(token)}`);

  // Connection status — so the UI can show "Live" as soon as the channel is up,
  // not only once the first ticket event happens to arrive.
  es.onopen = () => onEvent("stream:open", null);
  es.onerror = () => onEvent("stream:error", null);
  es.addEventListener("ready", () => onEvent("stream:open", null));

  const events = ["exception:created", "exception:critical", "exception:updated", "exception:deleted", "attendance:override"];
  const handlers = events.map((name) => {
    const fn = (m) => {
      let payload = null;
      try { payload = JSON.parse(m.data); } catch { /* ignore */ }
      onEvent(name, payload);
    };
    es.addEventListener(name, fn);
    return [name, fn];
  });

  return () => {
    handlers.forEach(([name, fn]) => es.removeEventListener(name, fn));
    es.onopen = null;
    es.onerror = null;
    es.close();
  };
}

/** DB returns ISO timestamps; render as HH:MM. */
export function fmtTime(v) {
  if (!v) return "";
  if (/^\d{2}:\d{2}$/.test(v)) return v;
  const d = new Date(v);
  return isNaN(d) ? String(v) : d.toLocaleTimeString("en-SG", { hour: "2-digit", minute: "2-digit", hour12: false });
}

input.content:
/* =============================================================================
 *  OWNED BY:  Jayden — Exception Logging & QR Fallback
 *  Screen 5 — Exception Inbox / Support Tickets
 *
 *  Full ticket CRUD over the shared backend:
 *    create  → POST   /api/trips/:id/exceptions   ("Log exception")
 *    read    → GET    /api/trips/:id/exceptions   (All / Critical / Open / Resolved)
 *    update  → PATCH  /api/exceptions/:id         (resolve, escalate)
 *    delete  → DELETE /api/exceptions/:id         (raised in error)
 *  Plus manual attendance override and a live critical-alert banner (SSE).
 *
 *  FILTERING IS CLIENT-SIDE. The list endpoint accepts status/priority filters,
 *  but this screen fetches the trip's tickets once and slices them in the
 *  browser instead. One trip's exception list is small (tens of rows, not
 *  thousands), and doing it here buys three things a per-tab round-trip can't:
 *  tabs switch with no spinner, the search box filters as you type, and the
 *  summary tiles stay computed over EVERY ticket rather than just the tab you
 *  happen to be looking at. The server's counts are still the source of truth
 *  for the tab badges.
 * ============================================================================= */
import { useEffect, useMemo, useState, useCallback } from "react";
import {
  AlertTriangle, Plus, UserCheck, Search, Download, ChevronsUp,
  CheckCircle2, Clock, Timer, X,
} from "lucide-react";
import { PieChart, Pie, Cell, ResponsiveContainer, Tooltip } from "recharts";
import StatusBadge from "../components/StatusBadge.jsx";
import LogExceptionModal from "../components/LogExceptionModal.jsx";
import { getPermissions } from "../lib/api.js";
import {
  listExceptions, resolveException, deleteException, manualOverride, updatePriority,
  subscribeStream, fmtTime, issueLabel, ageMinutes, fmtAge, ageLevel, resolveMinutes,
  exportTicketsCsv,
} from "../lib/exceptionsApi.js";
import "./ExceptionInboxPage.css";

const TABS = [
  { key: "All",      countKey: "all",      filter: {} },
  { key: "Critical", countKey: "critical", filter: { priority: "CRITICAL" } },
  { key: "Open",     countKey: "open",     filter: { status: "OPEN" } },
  { key: "Resolved", countKey: "resolved", filter: { status: "RESOLVED" } },
];

/* Donut slice colours, reused from the five-state palette so the chart reads as
 * part of the same system as the pills. Cycled if there are more issue types. */
const SLICE_COLOURS = [
  "var(--st-missing)", "var(--st-normal)", "var(--st-review)",
  "var(--st-present)", "var(--st-unassigned)", "var(--st-neutral)",
];

/** Ages tick over in the background, so re-render on a timer rather than only
 *  when a ticket changes — otherwise "8m" would sit there stale for an hour. */
const AGE_TICK_MS = 30000;

export default function ExceptionInboxPage() {
  const canEdit = getPermissions().manageExceptions; // view-for-all, edit-gated (see permissions.js)
  const [tab, setTab] = useState("All");
  const [allTickets, setAllTickets] = useState([]);
  const [counts, setCounts] = useState({ all: 0, critical: 0, open: 0, resolved: 0, criticalOpen: 0 });
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState("");
  const [live, setLive] = useState(false);
  const [modalOpen, setModalOpen] = useState(false);
  const [toast, setToast] = useState("");
  const [busyId, setBusyId] = useState(null);
  const [query, setQuery] = useState("");
  const [selected, setSelected] = useState(() => new Set());
  const [bulkBusy, setBulkBusy] = useState(false);
  const [now, setNow] = useState(() => Date.now());

  useEffect(() => {
    const id = setInterval(() => setNow(Date.now()), AGE_TICK_MS);
    return () => clearInterval(id);
  }, []);

  const load = useCallback(async () => {
    setError("");
    try {
      const { tickets, counts } = await listExceptions(); // unfiltered — sliced below
      setAllTickets(tickets);
      setCounts(counts);
      // Drop selections for tickets that no longer exist or are no longer open.
      setSelected((prev) => {
        if (!prev.size) return prev;
        const openIds = new Set(tickets.filter((t) => t.status === "OPEN").map((t) => t.id));
        const next = new Set([...prev].filter((id) => openIds.has(id)));
        return next.size === prev.size ? prev : next;
      });
    } catch (e) {
      setError(e.message || "Couldn't load tickets.");
    } finally {
      setLoading(false);
    }
  }, []);

  useEffect(() => { setLoading(true); load(); }, [load]);

  // Live updates: any ticket change anywhere refreshes this inbox.
  useEffect(() => {
    const unsub = subscribeStream((event) => {
      if (event === "stream:open")  { setLive(true);  return; }
      if (event === "stream:error") { setLive(false); return; }
      setLive(true);
      load();
      if (event === "exception:critical") flash("Critical alert pushed to all staff devices");
    });
    return unsub;
  }, [load]);

  function flash(msg) { setToast(msg); setTimeout(() => setToast(""), 2800); }

  async function act(id, fn, okMsg) {
    setBusyId(id);
    try {
      await fn();
      flash(okMsg);
      await load();
    } catch (e) {
      flash(e.code === "ALREADY_RESOLVED" ? "That ticket was already resolved" : (e.message || "Action failed"));
      await load();
    } finally {
      setBusyId(null);
    }
  }

  function handleCreated(_t, wasCritical) {
    setModalOpen(false);
    flash(wasCritical ? "Critical alert pushed to all staff devices" : "Exception logged");
    load();
  }

  /* ---- Slicing: tab, then search ---------------------------------------- */
  const byTab = useMemo(() => {
    const f = TABS.find((t) => t.key === tab).filter;
    return allTickets.filter(
      (t) => (!f.status || t.status === f.status) && (!f.priority || t.priority === f.priority)
    );
  }, [allTickets, tab]);

  const tickets = useMemo(() => {
    const q = query.trim().toLowerCase();
    if (!q) return byTab;
    return byTab.filter((t) =>
      [issueLabel(t), t.delegateName, t.coach, t.note, t.raisedBy, t.resolvedBy]
        .some((v) => (v || "").toLowerCase().includes(q))
    );
  }, [byTab, query]);

  /* ---- Summary tiles: always over ALL tickets, never just the tab -------- */
  const stats = useMemo(() => {
    const resolved = allTickets.filter((t) => t.status === "RESOLVED");
    const mins = resolved.map(resolveMinutes).filter((m) => m != null);
    const avg = mins.length ? Math.round(mins.reduce((a, b) => a + b, 0) / mins.length) : null;

    const midnight = new Date(); midnight.setHours(0, 0, 0, 0);
    const today = resolved.filter((t) => t.resolvedAt && new Date(t.resolvedAt) >= midnight).length;

    const open = allTickets.filter((t) => t.status === "OPEN");
    const oldest = open.reduce((max, t) => Math.max(max, ageMinutes(t.createdAt, now) ?? 0), 0);

    return { avg, today, oldest, openCount: open.length };
  }, [allTickets, now]);

  /* Open tickets grouped by issue type — the donut. */
  const mix = useMemo(() => {
    const by = new Map();
    allTickets.filter((t) => t.status === "OPEN").forEach((t) => {
      const k = issueLabel(t);
      by.set(k, (by.get(k) || 0) + 1);
    });
    return [...by.entries()].map(([name, value]) => ({ name, value })).sort((a, b) => b.value - a.value);
  }, [allTickets]);

  /* ---- Bulk selection ---------------------------------------------------- */
  const selectableIds = useMemo(
    () => tickets.filter((t) => t.status === "OPEN").map((t) => t.id),
    [tickets]
  );
  const allSelected = selectableIds.length > 0 && selectableIds.every((id) => selected.has(id));

  function toggleOne(id) {
    setSelected((prev) => {
      const next = new Set(prev);
      next.has(id) ? next.delete(id) : next.add(id);
      return next;
    });
  }
  function toggleAll() {
    setSelected((prev) => (allSelected ? new Set() : new Set([...prev, ...selectableIds])));
  }

  async function resolveSelected() {
    const ids = [...selected];
    if (!ids.length) return;
    setBulkBusy(true);
    let ok = 0, already = 0, failed = 0;
    // Sequential: each PATCH broadcasts over SSE, and a burst of parallel writes
    // would have every listener re-fetching the list N times over.
    for (const id of ids) {
      try { await resolveException(id); ok += 1; }
      catch (e) { e.code === "ALREADY_RESOLVED" ? (already += 1) : (failed += 1); }
    }
    setSelected(new Set());
    setBulkBusy(false);
    await load();
    const bits = [`${ok} resolved`];
    if (already) bits.push(`${already} already done`);
    if (failed) bits.push(`${failed} failed`);
    flash(bits.join(" · "));
  }

  function handleExport() {
    if (!tickets.length) { flash("Nothing to export in this view"); return; }
    const stamp = new Date().toISOString().slice(0, 10);
    const n = exportTicketsCsv(tickets, `exceptions-${tab.toLowerCase()}-${stamp}.csv`);
    flash(`Exported ${n} ticket${n === 1 ? "" : "s"}`);
  }

  const critical = tickets.find((t) => t.priority === "CRITICAL" && t.status === "OPEN");

  /* ---- Row actions -------------------------------------------------------
   * Override is the manual attendance fallback: LOST_BADGE / FACE_MATCH_FAILED /
   * DEAD_PHONE all describe someone standing right there who simply cannot be
   * scanned, and resolving the ticket only closes the admin task — it does not
   * (and must not) mark attendance, since a VIP_REQUEST or OTHER ticket has no
   * attendance meaning at all. So the button stays, but only while it can still
   * do something: once the delegate is PRESENT it is replaced by a marker, which
   * also stops repeat clicks writing duplicate check_in_logs rows.
   * ----------------------------------------------------------------------- */
  const rowActions = (t) => {
    if (!canEdit) return null;
    const present = t.delegateStatus === "PRESENT";
    return (
      <div className="exc-actions">
        {t.status === "OPEN" && (
          <>
            <button className="exc-btn-sm resolve" disabled={busyId === t.id}
              onClick={() => act(t.id, () => resolveException(t.id), "Ticket resolved")}>
              Resolve
            </button>
            {t.priority !== "CRITICAL" && (
              <button className="exc-btn-sm escalate" disabled={busyId === t.id}
                title="Raise to critical — pushes an alert to all staff devices"
                onClick={() => act(t.id, () => updatePriority(t.id, "CRITICAL"), "Escalated — alert pushed to all staff")}>
                <ChevronsUp size={14} /> Escalate
              </button>
            )}
            {t.delegateId && !present && (
              <button className="exc-btn-sm" disabled={busyId === t.id}
                title="Count this delegate present without a scan"
                onClick={() => act(t.id, () => manualOverride(t.delegateId), `${t.delegateName} marked present`)}>
                <UserCheck size={14} /> Override
              </button>
            )}
            {t.delegateId && present && (
              <span className="exc-present-tag" title="Already checked in — nothing to override">
                <CheckCircle2 size={14} /> Present
              </span>
            )}
          </>
        )}
        <button className="exc-btn-sm danger" disabled={busyId === t.id}
          onClick={() => act(t.id, () => deleteException(t.id), "Ticket deleted")}>
          Delete
        </button>
      </div>
    );
  };

  /** Raised-at cell: time, who, and how long it has been sitting. */
  const raisedCell = (t) => {
    const lvl = ageLevel(t, now);
    return (
      <>
        <div className="muted">{fmtTime(t.createdAt)} · {t.raisedBy}</div>
        {t.status === "OPEN" && (
          <span className={"exc-age" + (lvl ? " " + lvl : "")}>
            <Clock size={11} /> {fmtAge(ageMinutes(t.createdAt, now))}
          </span>
        )}
        {t.status === "RESOLVED" && t.resolvedAt && (
          <span className="exc-resolved-meta">
            resolved {fmtTime(t.resolvedAt)}
            {t.resolvedBy ? ` · ${t.resolvedBy}` : ""}
            {resolveMinutes(t) != null ? ` · took ${fmtAge(resolveMinutes(t))}` : ""}
          </span>
        )}
      </>
    );
  };

  const tiles = (
    <div className="exc-stats">
      <div className="exc-stat">
        <div className="exc-stat__label">Open</div>
        <div className="exc-stat__value">{counts.open ?? 0}</div>
        <div className="exc-stat__foot">{counts.all ?? 0} total</div>
      </div>
      <div className={"exc-stat" + ((counts.criticalOpen ?? 0) > 0 ? " danger" : "")}>
        <div className="exc-stat__label">Critical open</div>
        <div className="exc-stat__value">{counts.criticalOpen ?? 0}</div>
        <div className="exc-stat__foot">{counts.critical ?? 0} ever raised</div>
      </div>
      <div className="exc-stat">
        <div className="exc-stat__label">Avg resolve</div>
        <div className="exc-stat__value">{stats.avg == null ? "—" : fmtAge(stats.avg)}</div>
        <div className="exc-stat__foot">{counts.resolved ?? 0} resolved</div>
      </div>
      <div className={"exc-stat" + (stats.oldest >= 30 ? " danger" : stats.oldest >= 15 ? " warn" : "")}>
        <div className="exc-stat__label">Oldest open</div>
        <div className="exc-stat__value">{stats.openCount ? fmtAge(stats.oldest) : "—"}</div>
        <div className="exc-stat__foot">{stats.today} resolved today</div>
      </div>

      <div className="exc-stat exc-mix">
        <div className="exc-stat__label">Open by issue</div>
        {mix.length === 0 ? (
          <div className="exc-mix__empty">Nothing open</div>
        ) : (
          <div className="exc-mix__body">
            <div className="exc-mix__chart">
              <ResponsiveContainer width="100%" height="100%">
                <PieChart>
                  <Pie data={mix} dataKey="value" nameKey="name" innerRadius="58%" outerRadius="100%"
                       paddingAngle={2} stroke="none" isAnimationActive={false}>
                    {mix.map((_, i) => <Cell key={i} fill={SLICE_COLOURS[i % SLICE_COLOURS.length]} />)}
                  </Pie>
                  <Tooltip formatter={(v, n) => [`${v} open`, n]} />
                </PieChart>
              </ResponsiveContainer>
            </div>
            <ul className="exc-mix__legend">
              {mix.slice(0, 4).map((m, i) => (
                <li key={m.name}>
                  <span className="swatch" style={{ background: SLICE_COLOURS[i % SLICE_COLOURS.length] }} />
                  <span className="lbl">{m.name}</span>
                  <span className="num">{m.value}</span>
                </li>
              ))}
              {mix.length > 4 && <li className="more">+{mix.length - 4} more</li>}
            </ul>
          </div>
        )}
      </div>
    </div>
  );

  return (
    <div className="page">
      <div className="exc-header">
        <div>
          <div className="page-eyebrow">Beijing study mission · Day 3</div>
          <h1 className="page-title">Exception inbox</h1>
          <p className="page-sub">Log and resolve on-site exceptions; critical alerts push to all staff.</p>
        </div>
        <span className={"exc-live" + (live ? "" : " off")}>
          <span className="dot" /> {live ? "Live" : "Connecting…"}
        </span>
      </div>

      {tiles}

      {critical && (
        <div className="exc-banner">
          <div className="row" style={{ alignItems: "flex-start" }}>
            <AlertTriangle size={22} color="var(--scc-red)" strokeWidth={2.2} />
            <div>
              <div className="exc-banner__title">
                {counts.criticalOpen} critical exception{counts.criticalOpen === 1 ? "" : "s"} · pushed to all staff devices
              </div>
              <div className="exc-banner__sub">
                {issueLabel(critical)} · {critical.coach || "Unassigned"} ·{" "}
                {critical.delegateName || "Unidentified"} · raised {fmtTime(critical.createdAt)}
              </div>
            </div>
          </div>
          {canEdit && (
            <button className="btn btn-primary" style={{ flexShrink: 0 }} disabled={busyId === critical.id}
              onClick={() => act(critical.id, () => resolveException(critical.id), "Critical ticket resolved")}>
              Resolve now
            </button>
          )}
        </div>
      )}

      <div className="exc-toolbar">
        <div className="exc-tabs" role="tablist">
          {TABS.map(({ key, countKey }) => (
            <button key={key} role="tab" aria-selected={tab === key}
              className={"exc-tab" + (tab === key ? " active" : "")} onClick={() => setTab(key)}>
              {key} <span className="count">· {counts[countKey] ?? 0}</span>
            </button>
          ))}
        </div>
        <div className="exc-toolbar__right">
          <div className="exc-search">
            <Search size={15} />
            <input
              className="exc-search__input"
              placeholder="Search delegate, coach, issue…"
              value={query}
              onChange={(e) => setQuery(e.target.value)}
              aria-label="Search tickets"
            />
            {query && (
              <button className="exc-search__x" onClick={() => setQuery("")} aria-label="Clear search">
                <X size={14} />
              </button>
            )}
          </div>
          <button className="btn btn-ghost" onClick={handleExport} title="Download this view as CSV">
            <Download size={15} /> Export
          </button>
          {canEdit && (
            <button className="btn btn-primary" onClick={() => setModalOpen(true)}>
              <Plus size={16} strokeWidth={2.5} /> Log exception
            </button>
          )}
        </div>
      </div>

      {query && !loading && (
        <div className="exc-filterbar">
          Showing {tickets.length} of {byTab.length} in {tab}
          <button className="exc-btn-sm" onClick={() => setQuery("")}>Clear</button>
        </div>
      )}

      {canEdit && selected.size > 0 && (
        <div className="exc-bulkbar">
          <span><strong>{selected.size}</strong> selected</span>
          <div className="row" style={{ gap: 8 }}>
            <button className="exc-btn-sm" onClick={() => setSelected(new Set())} disabled={bulkBusy}>Clear</button>
            <button className="btn btn-primary" onClick={resolveSelected} disabled={bulkBusy}>
              <CheckCircle2 size={15} /> {bulkBusy ? "Resolving…" : `Resolve ${selected.size}`}
            </button>
          </div>
        </div>
      )}

      {/* Desktop table */}
      <div className="card exc-table-wrap" style={{ padding: 4 }}>
        <table className="table">
          <thead>
            <tr>
              {canEdit && (
                <th className="exc-checkcol">
                  <input type="checkbox" checked={allSelected} onChange={toggleAll}
                         disabled={!selectableIds.length} aria-label="Select all open tickets" />
                </th>
              )}
              <th>Priority</th><th>Issue</th><th>Delegate</th>
              <th>Coach</th><th>Raised</th><th>Status</th><th></th>
            </tr>
          </thead>
          <tbody>
            {loading && Array.from({ length: 4 }).map((_, i) => (
              <tr key={i}><td colSpan={canEdit ? 8 : 7}><div className="exc-skeleton" /></td></tr>
            ))}

            {!loading && !error && tickets.map((t) => (
              <tr key={t.id} className={selected.has(t.id) ? "exc-row-sel" : ""}>
                {canEdit && (
                  <td className="exc-checkcol">
                    {t.status === "OPEN" && (
                      <input type="checkbox" checked={selected.has(t.id)} onChange={() => toggleOne(t.id)}
                             aria-label={`Select ticket ${issueLabel(t)}`} />
                    )}
                  </td>
                )}
                <td><StatusBadge state={t.priority} /></td>
                <td>
                  <div className="exc-issue-title">
                    {issueLabel(t)}
                    {t.delegateVip && <span className="exc-vip">VIP</span>}
                  </div>
                  <div className="exc-issue-sub">{t.note}</div>
                </td>
                <td>{t.delegateName || "Unidentified"}</td>
                <td>{t.coach || "—"}</td>
                <td>{raisedCell(t)}</td>
                <td><StatusBadge state={t.status} /></td>
                <td>{rowActions(t)}</td>
              </tr>
            ))}

            {!loading && !error && tickets.length === 0 && (
              <tr><td colSpan={canEdit ? 8 : 7}>
                <div className="exc-state">
                  {query ? `No tickets match “${query}”.` : "All clear — no tickets in this view."}
                </div>
              </td></tr>
            )}
            {error && (
              <tr><td colSpan={canEdit ? 8 : 7}>
                <div className="exc-state">
                  {error} <button className="exc-btn-sm" onClick={load} style={{ marginLeft: 8 }}>Retry</button>
                </div>
              </td></tr>
            )}
          </tbody>
        </table>
      </div>

      {/* Mobile cards */}
      <div className="card exc-cards">
        {loading && Array.from({ length: 3 }).map((_, i) => (
          <div className="exc-card" key={i}><div className="exc-skeleton" /></div>
        ))}
        {!loading && !error && tickets.map((t) => (
          <div className="exc-card" key={t.id}>
            <div className="exc-card__top">
              <div className="row" style={{ gap: 8, alignItems: "center" }}>
                {canEdit && t.status === "OPEN" && (
                  <input type="checkbox" checked={selected.has(t.id)} onChange={() => toggleOne(t.id)}
                         aria-label={`Select ticket ${issueLabel(t)}`} />
                )}
                <StatusBadge state={t.priority} />
              </div>
              <StatusBadge state={t.status} />
            </div>
            <div className="exc-issue-title">
              {issueLabel(t)}
              {t.delegateVip && <span className="exc-vip">VIP</span>}
            </div>
            <div className="exc-issue-sub">{t.note}</div>
            <div className="exc-card__meta">{t.delegateName || "Unidentified"} · {t.coach || "—"}</div>
            <div className="exc-card__meta">{raisedCell(t)}</div>
            {rowActions(t)}
          </div>
        ))}
        {!loading && !error && tickets.length === 0 && (
          <div className="exc-state">
            {query ? `No tickets match “${query}”.` : "All clear — no tickets in this view."}
          </div>
        )}
        {error && <div className="exc-state">{error} <button className="exc-btn-sm" onClick={load}>Retry</button></div>}
      </div>

      {modalOpen && <LogExceptionModal onClose={() => setModalOpen(false)} onCreated={handleCreated} />}
      {toast && <div className="exc-toast">{toast}</div>}
    </div>
  );
}

toolUseResult.content:
/* =============================================================================
 *  OWNED BY:  Jayden — Exception Logging & QR Fallback
 *  Screen 5 — Exception Inbox / Support Tickets
 *
 *  Full ticket CRUD over the shared backend:
 *    create  → POST   /api/trips/:id/exceptions   ("Log exception")
 *    read    → GET    /api/trips/:id/exceptions   (All / Critical / Open / Resolved)
 *    update  → PATCH  /api/exceptions/:id         (resolve, escalate)
 *    delete  → DELETE /api/exceptions/:id         (raised in error)
 *  Plus manual attendance override and a live critical-alert banner (SSE).
 *
 *  FILTERING IS CLIENT-SIDE. The list endpoint accepts status/priority filters,
 *  but this screen fetches the trip's tickets once and slices them in the
 *  browser instead. One trip's exception list is small (tens of rows, not
 *  thousands), and doing it here buys three things a per-tab round-trip can't:
 *  tabs switch with no spinner, the search box filters as you type, and the
 *  summary tiles stay computed over EVERY ticket rather than just the tab you
 *  happen to be looking at. The server's counts are still the source of truth
 *  for the tab badges.
 * ============================================================================= */
import { useEffect, useMemo, useState, useCallback } from "react";
import {
  AlertTriangle, Plus, UserCheck, Search, Download, ChevronsUp,
  CheckCircle2, Clock, Timer, X,
} from "lucide-react";
import { PieChart, Pie, Cell, ResponsiveContainer, Tooltip } from "recharts";
import StatusBadge from "../components/StatusBadge.jsx";
import LogExceptionModal from "../components/LogExceptionModal.jsx";
import { getPermissions } from "../lib/api.js";
import {
  listExceptions, resolveException, deleteException, manualOverride, updatePriority,
  subscribeStream, fmtTime, issueLabel, ageMinutes, fmtAge, ageLevel, resolveMinutes,
  exportTicketsCsv,
} from "../lib/exceptionsApi.js";
import "./ExceptionInboxPage.css";

const TABS = [
  { key: "All",      countKey: "all",      filter: {} },
  { key: "Critical", countKey: "critical", filter: { priority: "CRITICAL" } },
  { key: "Open",     countKey: "open",     filter: { status: "OPEN" } },
  { key: "Resolved", countKey: "resolved", filter: { status: "RESOLVED" } },
];

/* Donut slice colours, reused from the five-state palette so the chart reads as
 * part of the same system as the pills. Cycled if there are more issue types. */
const SLICE_COLOURS = [
  "var(--st-missing)", "var(--st-normal)", "var(--st-review)",
  "var(--st-present)", "var(--st-unassigned)", "var(--st-neutral)",
];

/** Ages tick over in the background, so re-render on a timer rather than only
 *  when a ticket changes — otherwise "8m" would sit there stale for an hour. */
const AGE_TICK_MS = 30000;

export default function ExceptionInboxPage() {
  const canEdit = getPermissions().manageExceptions; // view-for-all, edit-gated (see permissions.js)
  const [tab, setTab] = useState("All");
  const [allTickets, setAllTickets] = useState([]);
  const [counts, setCounts] = useState({ all: 0, critical: 0, open: 0, resolved: 0, criticalOpen: 0 });
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState("");
  const [live, setLive] = useState(false);
  const [modalOpen, setModalOpen] = useState(false);
  const [toast, setToast] = useState("");
  const [busyId, setBusyId] = useState(null);
  const [query, setQuery] = useState("");
  const [selected, setSelected] = useState(() => new Set());
  const [bulkBusy, setBulkBusy] = useState(false);
  const [now, setNow] = useState(() => Date.now());

  useEffect(() => {
    const id = setInterval(() => setNow(Date.now()), AGE_TICK_MS);
    return () => clearInterval(id);
  }, []);

  const load = useCallback(async () => {
    setError("");
    try {
      const { tickets, counts } = await listExceptions(); // unfiltered — sliced below
      setAllTickets(tickets);
      setCounts(counts);
      // Drop selections for tickets that no longer exist or are no longer open.
      setSelected((prev) => {
        if (!prev.size) return prev;
        const openIds = new Set(tickets.filter((t) => t.status === "OPEN").map((t) => t.id));
        const next = new Set([...prev].filter((id) => openIds.has(id)));
        return next.size === prev.size ? prev : next;
      });
    } catch (e) {
      setError(e.message || "Couldn't load tickets.");
    } finally {
      setLoading(false);
    }
  }, []);

  useEffect(() => { setLoading(true); load(); }, [load]);

  // Live updates: any ticket change anywhere refreshes this inbox.
  useEffect(() => {
    const unsub = subscribeStream((event) => {
      if (event === "stream:open")  { setLive(true);  return; }
      if (event === "stream:error") { setLive(false); return; }
      setLive(true);
      load();
      if (event === "exception:critical") flash("Critical alert pushed to all staff devices");
    });
    return unsub;
  }, [load]);

  function flash(msg) { setToast(msg); setTimeout(() => setToast(""), 2800); }

  async function act(id, fn, okMsg) {
    setBusyId(id);
    try {
      await fn();
      flash(okMsg);
      await load();
    } catch (e) {
      flash(e.code === "ALREADY_RESOLVED" ? "That ticket was already resolved" : (e.message || "Action failed"));
      await load();
    } finally {
      setBusyId(null);
    }
  }

  function handleCreated(_t, wasCritical) {
    setModalOpen(false);
    flash(wasCritical ? "Critical alert pushed to all staff devices" : "Exception logged");
    load();
  }

  /* ---- Slicing: tab, then search ---------------------------------------- */
  const byTab = useMemo(() => {
    const f = TABS.find((t) => t.key === tab).filter;
    return allTickets.filter(
      (t) => (!f.status || t.status === f.status) && (!f.priority || t.priority === f.priority)
    );
  }, [allTickets, tab]);

  const tickets = useMemo(() => {
    const q = query.trim().toLowerCase();
    if (!q) return byTab;
    return byTab.filter((t) =>
      [issueLabel(t), t.delegateName, t.coach, t.note, t.raisedBy, t.resolvedBy]
        .some((v) => (v || "").toLowerCase().includes(q))
    );
  }, [byTab, query]);

  /* ---- Summary tiles: always over ALL tickets, never just the tab -------- */
  const stats = useMemo(() => {
    const resolved = allTickets.filter((t) => t.status === "RESOLVED");
    const mins = resolved.map(resolveMinutes).filter((m) => m != null);
    const avg = mins.length ? Math.round(mins.reduce((a, b) => a + b, 0) / mins.length) : null;

    const midnight = new Date(); midnight.setHours(0, 0, 0, 0);
    const today = resolved.filter((t) => t.resolvedAt && new Date(t.resolvedAt) >= midnight).length;

    const open = allTickets.filter((t) => t.status === "OPEN");
    const oldest = open.reduce((max, t) => Math.max(max, ageMinutes(t.createdAt, now) ?? 0), 0);

    return { avg, today, oldest, openCount: open.length };
  }, [allTickets, now]);

  /* Open tickets grouped by issue type — the donut. */
  const mix = useMemo(() => {
    const by = new Map();
    allTickets.filter((t) => t.status === "OPEN").forEach((t) => {
      const k = issueLabel(t);
      by.set(k, (by.get(k) || 0) + 1);
    });
    return [...by.entries()].map(([name, value]) => ({ name, value })).sort((a, b) => b.value - a.value);
  }, [allTickets]);

  /* ---- Bulk selection ---------------------------------------------------- */
  const selectableIds = useMemo(
    () => tickets.filter((t) => t.status === "OPEN").map((t) => t.id),
    [tickets]
  );
  const allSelected = selectableIds.length > 0 && selectableIds.every((id) => selected.has(id));

  function toggleOne(id) {
    setSelected((prev) => {
      const next = new Set(prev);
      next.has(id) ? next.delete(id) : next.add(id);
      return next;
    });
  }
  function toggleAll() {
    setSelected((prev) => (allSelected ? new Set() : new Set([...prev, ...selectableIds])));
  }

  async function resolveSelected() {
    const ids = [...selected];
    if (!ids.length) return;
    setBulkBusy(true);
    let ok = 0, already = 0, failed = 0;
    // Sequential: each PATCH broadcasts over SSE, and a burst of parallel writes
    // would have every listener re-fetching the list N times over.
    for (const id of ids) {
      try { await resolveException(id); ok += 1; }
      catch (e) { e.code === "ALREADY_RESOLVED" ? (already += 1) : (failed += 1); }
    }
    setSelected(new Set());
    setBulkBusy(false);
    await load();
    const bits = [`${ok} resolved`];
    if (already) bits.push(`${already} already done`);
    if (failed) bits.push(`${failed} failed`);
    flash(bits.join(" · "));
  }

  function handleExport() {
    if (!tickets.length) { flash("Nothing to export in this view"); return; }
    const stamp = new Date().toISOString().slice(0, 10);
    const n = exportTicketsCsv(tickets, `exceptions-${tab.toLowerCase()}-${stamp}.csv`);
    flash(`Exported ${n} ticket${n === 1 ? "" : "s"}`);
  }

  const critical = tickets.find((t) => t.priority === "CRITICAL" && t.status === "OPEN");

  /* ---- Row actions -------------------------------------------------------
   * Override is the manual attendance fallback: LOST_BADGE / FACE_MATCH_FAILED /
   * DEAD_PHONE all describe someone standing right there who simply cannot be
   * scanned, and resolving the ticket only closes the admin task — it does not
   * (and must not) mark attendance, since a VIP_REQUEST or OTHER ticket has no
   * attendance meaning at all. So the button stays, but only while it can still
   * do something: once the delegate is PRESENT it is replaced by a marker, which
   * also stops repeat clicks writing duplicate check_in_logs rows.
   * ----------------------------------------------------------------------- */
  const rowActions = (t) => {
    if (!canEdit) return null;
    const present = t.delegateStatus === "PRESENT";
    return (
      <div className="exc-actions">
        {t.status === "OPEN" && (
          <>
            <button className="exc-btn-sm resolve" disabled={busyId === t.id}
              onClick={() => act(t.id, () => resolveException(t.id), "Ticket resolved")}>
              Resolve
            </button>
            {t.priority !== "CRITICAL" && (
              <button className="exc-btn-sm escalate" disabled={busyId === t.id}
                title="Raise to critical — pushes an alert to all staff devices"
                onClick={() => act(t.id, () => updatePriority(t.id, "CRITICAL"), "Escalated — alert pushed to all staff")}>
                <ChevronsUp size={14} /> Escalate
              </button>
            )}
            {t.delegateId && !present && (
              <button className="exc-btn-sm" disabled={busyId === t.id}
                title="Count this delegate present without a scan"
                onClick={() => act(t.id, () => manualOverride(t.delegateId), `${t.delegateName} marked present`)}>
                <UserCheck size={14} /> Override
              </button>
            )}
            {t.delegateId && present && (
              <span className="exc-present-tag" title="Already checked in — nothing to override">
                <CheckCircle2 size={14} /> Present
              </span>
            )}
          </>
        )}
        <button className="exc-btn-sm danger" disabled={busyId === t.id}
          onClick={() => act(t.id, () => deleteException(t.id), "Ticket deleted")}>
          Delete
        </button>
      </div>
    );
  };

  /** Raised-at cell: time, who, and how long it has been sitting. */
  const raisedCell = (t) => {
    const lvl = ageLevel(t, now);
    return (
      <>
        <div className="muted">{fmtTime(t.createdAt)} · {t.raisedBy}</div>
        {t.status === "OPEN" && (
          <span className={"exc-age" + (lvl ? " " + lvl : "")}>
            <Clock size={11} /> {fmtAge(ageMinutes(t.createdAt, now))}
          </span>
        )}
        {t.status === "RESOLVED" && t.resolvedAt && (
          <span className="exc-resolved-meta">
            resolved {fmtTime(t.resolvedAt)}
            {t.resolvedBy ? ` · ${t.resolvedBy}` : ""}
            {resolveMinutes(t) != null ? ` · took ${fmtAge(resolveMinutes(t))}` : ""}
          </span>
        )}
      </>
    );
  };

  const tiles = (
    <div className="exc-stats">
      <div className="exc-stat">
        <div className="exc-stat__label">Open</div>
        <div className="exc-stat__value">{counts.open ?? 0}</div>
        <div className="exc-stat__foot">{counts.all ?? 0} total</div>
      </div>
      <div className={"exc-stat" + ((counts.criticalOpen ?? 0) > 0 ? " danger" : "")}>
        <div className="exc-stat__label">Critical open</div>
        <div className="exc-stat__value">{counts.criticalOpen ?? 0}</div>
        <div className="exc-stat__foot">{counts.critical ?? 0} ever raised</div>
      </div>
      <div className="exc-stat">
        <div className="exc-stat__label">Avg resolve</div>
        <div className="exc-stat__value">{stats.avg == null ? "—" : fmtAge(stats.avg)}</div>
        <div className="exc-stat__foot">{counts.resolved ?? 0} resolved</div>
      </div>
      <div className={"exc-stat" + (stats.oldest >= 30 ? " danger" : stats.oldest >= 15 ? " warn" : "")}>
        <div className="exc-stat__label">Oldest open</div>
        <div className="exc-stat__value">{stats.openCount ? fmtAge(stats.oldest) : "—"}</div>
        <div className="exc-stat__foot">{stats.today} resolved today</div>
      </div>

      <div className="exc-stat exc-mix">
        <div className="exc-stat__label">Open by issue</div>
        {mix.length === 0 ? (
          <div className="exc-mix__empty">Nothing open</div>
        ) : (
          <div className="exc-mix__body">
            <div className="exc-mix__chart">
              <ResponsiveContainer width="100%" height="100%">
                <PieChart>
                  <Pie data={mix} dataKey="value" nameKey="name" innerRadius="58%" outerRadius="100%"
                       paddingAngle={2} stroke="none" isAnimationActive={false}>
                    {mix.map((_, i) => <Cell key={i} fill={SLICE_COLOURS[i % SLICE_COLOURS.length]} />)}
                  </Pie>
                  <Tooltip formatter={(v, n) => [`${v} open`, n]} />
                </PieChart>
              </ResponsiveContainer>
            </div>
            <ul className="exc-mix__legend">
              {mix.slice(0, 4).map((m, i) => (
                <li key={m.name}>
                  <span className="swatch" style={{ background: SLICE_COLOURS[i % SLICE_COLOURS.length] }} />
                  <span className="lbl">{m.name}</span>
                  <span className="num">{m.value}</span>
                </li>
              ))}
              {mix.length > 4 && <li className="more">+{mix.length - 4} more</li>}
            </ul>
          </div>
        )}
      </div>
    </div>
  );

  return (
    <div className="page">
      <div className="exc-header">
        <div>
          <div className="page-eyebrow">Beijing study mission · Day 3</div>
          <h1 className="page-title">Exception inbox</h1>
          <p className="page-sub">Log and resolve on-site exceptions; critical alerts push to all staff.</p>
        </div>
        <span className={"exc-live" + (live ? "" : " off")}>
          <span className="dot" /> {live ? "Live" : "Connecting…"}
        </span>
      </div>

      {tiles}

      {critical && (
        <div className="exc-banner">
          <div className="row" style={{ alignItems: "flex-start" }}>
            <AlertTriangle size={22} color="var(--scc-red)" strokeWidth={2.2} />
            <div>
              <div className="exc-banner__title">
                {counts.criticalOpen} critical exception{counts.criticalOpen === 1 ? "" : "s"} · pushed to all staff devices
              </div>
              <div className="exc-banner__sub">
                {issueLabel(critical)} · {critical.coach || "Unassigned"} ·{" "}
                {critical.delegateName || "Unidentified"} · raised {fmtTime(critical.createdAt)}
              </div>
            </div>
          </div>
          {canEdit && (
            <button className="btn btn-primary" style={{ flexShrink: 0 }} disabled={busyId === critical.id}
              onClick={() => act(critical.id, () => resolveException(critical.id), "Critical ticket resolved")}>
              Resolve now
            </button>
          )}
        </div>
      )}

      <div className="exc-toolbar">
        <div className="exc-tabs" role="tablist">
          {TABS.map(({ key, countKey }) => (
            <button key={key} role="tab" aria-selected={tab === key}
              className={"exc-tab" + (tab === key ? " active" : "")} onClick={() => setTab(key)}>
              {key} <span className="count">· {counts[countKey] ?? 0}</span>
            </button>
          ))}
        </div>
        <div className="exc-toolbar__right">
          <div className="exc-search">
            <Search size={15} />
            <input
              className="exc-search__input"
              placeholder="Search delegate, coach, issue…"
              value={query}
              onChange={(e) => setQuery(e.target.value)}
              aria-label="Search tickets"
            />
            {query && (
              <button className="exc-search__x" onClick={() => setQuery("")} aria-label="Clear search">
                <X size={14} />
              </button>
            )}
          </div>
          <button className="btn btn-ghost" onClick={handleExport} title="Download this view as CSV">
            <Download size={15} /> Export
          </button>
          {canEdit && (
            <button className="btn btn-primary" onClick={() => setModalOpen(true)}>
              <Plus size={16} strokeWidth={2.5} /> Log exception
            </button>
          )}
        </div>
      </div>

      {query && !loading && (
        <div className="exc-filterbar">
          Showing {tickets.length} of {byTab.length} in {tab}
          <button className="exc-btn-sm" onClick={() => setQuery("")}>Clear</button>
        </div>
      )}

      {canEdit && selected.size > 0 && (
        <div className="exc-bulkbar">
          <span><strong>{selected.size}</strong> selected</span>
          <div className="row" style={{ gap: 8 }}>
            <button className="exc-btn-sm" onClick={() => setSelected(new Set())} disabled={bulkBusy}>Clear</button>
            <button className="btn btn-primary" onClick={resolveSelected} disabled={bulkBusy}>
              <CheckCircle2 size={15} /> {bulkBusy ? "Resolving…" : `Resolve ${selected.size}`}
            </button>
          </div>
        </div>
      )}

      {/* Desktop table */}
      <div className="card exc-table-wrap" style={{ padding: 4 }}>
        <table className="table">
          <thead>
            <tr>
              {canEdit && (
                <th className="exc-checkcol">
                  <input type="checkbox" checked={allSelected} onChange={toggleAll}
                         disabled={!selectableIds.length} aria-label="Select all open tickets" />
                </th>
              )}
              <th>Priority</th><th>Issue</th><th>Delegate</th>
              <th>Coach</th><th>Raised</th><th>Status</th><th></th>
            </tr>
          </thead>
          <tbody>
            {loading && Array.from({ length: 4 }).map((_, i) => (
              <tr key={i}><td colSpan={canEdit ? 8 : 7}><div className="exc-skeleton" /></td></tr>
            ))}

            {!loading && !error && tickets.map((t) => (
              <tr key={t.id} className={selected.has(t.id) ? "exc-row-sel" : ""}>
                {canEdit && (
                  <td className="exc-checkcol">
                    {t.status === "OPEN" && (
                      <input type="checkbox" checked={selected.has(t.id)} onChange={() => toggleOne(t.id)}
                             aria-label={`Select ticket ${issueLabel(t)}`} />
                    )}
                  </td>
                )}
                <td><StatusBadge state={t.priority} /></td>
                <td>
                  <div className="exc-issue-title">
                    {issueLabel(t)}
                    {t.delegateVip && <span className="exc-vip">VIP</span>}
                  </div>
                  <div className="exc-issue-sub">{t.note}</div>
                </td>
                <td>{t.delegateName || "Unidentified"}</td>
                <td>{t.coach || "—"}</td>
                <td>{raisedCell(t)}</td>
                <td><StatusBadge state={t.status} /></td>
                <td>{rowActions(t)}</td>
              </tr>
            ))}

            {!loading && !error && tickets.length === 0 && (
              <tr><td colSpan={canEdit ? 8 : 7}>
                <div className="exc-state">
                  {query ? `No tickets match “${query}”.` : "All clear — no tickets in this view."}
                </div>
              </td></tr>
            )}
            {error && (
              <tr><td colSpan={canEdit ? 8 : 7}>
                <div className="exc-state">
                  {error} <button className="exc-btn-sm" onClick={load} style={{ marginLeft: 8 }}>Retry</button>
                </div>
              </td></tr>
            )}
          </tbody>
        </table>
      </div>

      {/* Mobile cards */}
      <div className="card exc-cards">
        {loading && Array.from({ length: 3 }).map((_, i) => (
          <div className="exc-card" key={i}><div className="exc-skeleton" /></div>
        ))}
        {!loading && !error && tickets.map((t) => (
          <div className="exc-card" key={t.id}>
            <div className="exc-card__top">
              <div className="row" style={{ gap: 8, alignItems: "center" }}>
                {canEdit && t.status === "OPEN" && (
                  <input type="checkbox" checked={selected.has(t.id)} onChange={() => toggleOne(t.id)}
                         aria-label={`Select ticket ${issueLabel(t)}`} />
                )}
                <StatusBadge state={t.priority} />
              </div>
              <StatusBadge state={t.status} />
            </div>
            <div className="exc-issue-title">
              {issueLabel(t)}
              {t.delegateVip && <span className="exc-vip">VIP</span>}
            </div>
            <div className="exc-issue-sub">{t.note}</div>
            <div className="exc-card__meta">{t.delegateName || "Unidentified"} · {t.coach || "—"}</div>
            <div className="exc-card__meta">{raisedCell(t)}</div>
            {rowActions(t)}
          </div>
        ))}
        {!loading && !error && tickets.length === 0 && (
          <div className="exc-state">
            {query ? `No tickets match “${query}”.` : "All clear — no tickets in this view."}
          </div>
        )}
        {error && <div className="exc-state">{error} <button className="exc-btn-sm" onClick={load}>Retry</button></div>}
      </div>

      {modalOpen && <LogExceptionModal onClose={() => setModalOpen(false)} onCreated={handleCreated} />}
      {toast && <div className="exc-toast">{toast}</div>}
    </div>
  );
}

toolUseResult.originalFile:
/* =============================================================================
 *  OWNED BY:  Jayden — Exception Logging & QR Fallback
 *  Screen 5 — Exception Inbox / Support Tickets
 *
 *  Full ticket CRUD over the shared backend:
 *    create  → POST   /api/trips/:id/exceptions   ("Log exception")
 *    read    → GET    /api/trips/:id/exceptions   (All / Critical / Open / Resolved)
 *    update  → PATCH  /api/exceptions/:id         (resolve, escalate)
 *    delete  → DELETE /api/exceptions/:id         (raised in error)
 *  Plus manual attendance override and a live critical-alert banner (SSE).
 * ============================================================================= */
import { useEffect, useState, useCallback } from "react";
import { AlertTriangle, Plus, UserCheck } from "lucide-react";
import StatusBadge from "../components/StatusBadge.jsx";
import LogExceptionModal from "../components/LogExceptionModal.jsx";
import { getPermissions } from "../lib/api.js";
import {
  listExceptions, resolveException, deleteException, manualOverride,
  subscribeStream, fmtTime, issueLabel,
} from "../lib/exceptionsApi.js";
import "./ExceptionInboxPage.css";

const TABS = [
  { key: "All",      countKey: "all",      filter: {} },
  { key: "Critical", countKey: "critical", filter: { priority: "CRITICAL" } },
  { key: "Open",     countKey: "open",     filter: { status: "OPEN" } },
  { key: "Resolved", countKey: "resolved", filter: { status: "RESOLVED" } },
];

export default function ExceptionInboxPage() {
  const canEdit = getPermissions().manageExceptions; // view-for-all, edit-gated (see permissions.js)
  const [tab, setTab] = useState("All");
  const [tickets, setTickets] = useState([]);
  const [counts, setCounts] = useState({ all: 0, critical: 0, open: 0, resolved: 0 });
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState("");
  const [live, setLive] = useState(false);
  const [modalOpen, setModalOpen] = useState(false);
  const [toast, setToast] = useState("");
  const [busyId, setBusyId] = useState(null);

  const activeFilter = TABS.find((t) => t.key === tab).filter;

  const load = useCallback(async () => {
    setError("");
    try {
      const { tickets, counts } = await listExceptions(activeFilter);
      setTickets(tickets);
      setCounts(counts);
    } catch (e) {
      setError(e.message || "Couldn't load tickets.");
    } finally {
      setLoading(false);
    }
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [tab]);

  useEffect(() => { setLoading(true); load(); }, [load]);

  // Live updates: any ticket change anywhere refreshes this inbox.
  useEffect(() => {
    const unsub = subscribeStream((event) => {
      if (event === "stream:open")  { setLive(true);  return; }
      if (event === "stream:error") { setLive(false); return; }
      setLive(true);
      load();
      if (event === "exception:critical") flash("Critical alert pushed to all staff devices");
    });
    return unsub;
  }, [load]);

  function flash(msg) { setToast(msg); setTimeout(() => setToast(""), 2800); }

  async function act(id, fn, okMsg) {
    setBusyId(id);
    try {
      await fn();
      flash(okMsg);
      await load();
    } catch (e) {
      flash(e.code === "ALREADY_RESOLVED" ? "That ticket was already resolved" : (e.message || "Action failed"));
      await load();
    } finally {
      setBusyId(null);
    }
  }

  function handleCreated(_t, wasCritical) {
    setModalOpen(false);
    flash(wasCritical ? "Critical alert pushed to all staff devices" : "Exception logged");
    load();
  }

  const critical = tickets.find((t) => t.priority === "CRITICAL" && t.status === "OPEN");

  const rowActions = (t) => canEdit && (
    <div className="exc-actions">
      {t.status === "OPEN" && (
        <>
          <button className="exc-btn-sm resolve" disabled={busyId === t.id}
            onClick={() => act(t.id, () => resolveException(t.id), "Ticket resolved")}>
            Resolve
          </button>
          {t.delegateId && (
            <button className="exc-btn-sm" disabled={busyId === t.id}
              title="Count this delegate present without a scan"
              onClick={() => act(t.id, () => manualOverride(t.delegateId), `${t.delegateName} marked present`)}>
              <UserCheck size={14} /> Override
            </button>
          )}
        </>
      )}
      <button className="exc-btn-sm danger" disabled={busyId === t.id}
        onClick={() => act(t.id, () => deleteException(t.id), "Ticket deleted")}>
        Delete
      </button>
    </div>
  );

  return (
    <div className="page">
      <div className="exc-header">
        <div>
          <div className="page-eyebrow">Beijing study mission · Day 3</div>
          <h1 className="page-title">Exception inbox</h1>
          <p className="page-sub">Log and resolve on-site exceptions; critical alerts push to all staff.</p>
        </div>
        <span className={"exc-live" + (live ? "" : " off")}>
          <span className="dot" /> {live ? "Live" : "Connecting…"}
        </span>
      </div>

      {critical && (
        <div className="exc-banner">
          <div className="row" style={{ alignItems: "flex-start" }}>
            <AlertTriangle size={22} color="var(--scc-red)" strokeWidth={2.2} />
            <div>
              <div className="exc-banner__title">
                {counts.critical} critical exception{counts.critical === 1 ? "" : "s"} · pushed to all staff devices
              </div>
              <div className="exc-banner__sub">
                {issueLabel(critical)} · {critical.coach || "Unassigned"} ·{" "}
                {critical.delegateName || "Unidentified"} · raised {fmtTime(critical.createdAt)}
              </div>
            </div>
          </div>
          {canEdit && (
            <button className="btn btn-primary" style={{ flexShrink: 0 }} disabled={busyId === critical.id}
              onClick={() => act(critical.id, () => resolveException(critical.id), "Critical ticket resolved")}>
              Resolve now
            </button>
          )}
        </div>
      )}

      <div className="exc-toolbar">
        <div className="exc-tabs" role="tablist">
          {TABS.map(({ key, countKey }) => (
            <button key={key} role="tab" aria-selected={tab === key}
              className={"exc-tab" + (tab === key ? " active" : "")} onClick={() => setTab(key)}>
              {key} <span className="count">· {counts[countKey] ?? 0}</span>
            </button>
          ))}
        </div>
        {canEdit && (
          <button className="btn btn-primary" onClick={() => setModalOpen(true)}>
            <Plus size={16} strokeWidth={2.5} /> Log exception
          </button>
        )}
      </div>

      {/* Desktop table */}
      <div className="card exc-table-wrap" style={{ padding: 4 }}>
        <table className="table">
          <thead>
            <tr>
              <th>Priority</th><th>Issue</th><th>Delegate</th>
              <th>Coach</th><th>Raised</th><th>Status</th><th></th>
            </tr>
          </thead>
          <tbody>
            {loading && Array.from({ length: 4 }).map((_, i) => (
              <tr key={i}><td colSpan={7}><div className="exc-skeleton" /></td></tr>
            ))}

            {!loading && !error && tickets.map((t) => (
              <tr key={t.id}>
                <td><StatusBadge state={t.priority} /></td>
                <td>
                  <div className="exc-issue-title">
                    {issueLabel(t)}
                    {t.delegateVip && <span className="exc-vip">VIP</span>}
                  </div>
                  <div className="exc-issue-sub">{t.note}</div>
                </td>
                <td>{t.delegateName || "Unidentified"}</td>
                <td>{t.coach || "—"}</td>
                <td className="muted">{fmtTime(t.createdAt)} · {t.raisedBy}</td>
                <td><StatusBadge state={t.status} /></td>
                <td>{rowActions(t)}</td>
              </tr>
            ))}

            {!loading && !error && tickets.length === 0 && (
              <tr><td colSpan={7}><div className="exc-state">All clear — no tickets in this view.</div></td></tr>
            )}
            {error && (
              <tr><td colSpan={7}>
                <div className="exc-state">
                  {error} <button className="exc-btn-sm" onClick={load} style={{ marginLeft: 8 }}>Retry</button>
                </div>
              </td></tr>
            )}
          </tbody>
        </table>
      </div>

      {/* Mobile cards */}
      <div className="card exc-cards">
        {loading && Array.from({ length: 3 }).map((_, i) => (
          <div className="exc-card" key={i}><div className="exc-skeleton" /></div>
        ))}
        {!loading && !error && tickets.map((t) => (
          <div className="exc-card" key={t.id}>
            <div className="exc-card__top">
              <StatusBadge state={t.priority} />
              <StatusBadge state={t.status} />
            </div>
            <div className="exc-issue-title">
              {issueLabel(t)}
              {t.delegateVip && <span className="exc-vip">VIP</span>}
            </div>
            <div className="exc-issue-sub">{t.note}</div>
            <div className="exc-card__meta">{t.delegateName || "Unidentified"} · {t.coach || "—"}</div>
            <div className="exc-card__meta">{fmtTime(t.createdAt)} · {t.raisedBy}</div>
            {rowActions(t)}
          </div>
        ))}
        {!loading && !error && tickets.length === 0 && <div className="exc-state">All clear — no tickets in this view.</div>}
        {error && <div className="exc-state">{error} <button className="exc-btn-sm" onClick={load}>Retry</button></div>}
      </div>

      {modalOpen && <LogExceptionModal onClose={() => setModalOpen(false)} onCreated={handleCreated} />}
      {toast && <div className="exc-toast">{toast}</div>}
    </div>
  );
}

