(async () => {
  // log in through the app's own API so the SPA has a real session
  const r = await fetch('/api/auth/login', {
    method: 'POST', headers: {'Content-Type':'application/json'},
    body: JSON.stringify({ staffId: 'staff_194', password: 'password123!' })
  });
  const d = await r.json();
  localStorage.setItem('mg_token', d.token);
  localStorage.setItem('mg_user', JSON.stringify({
    username: d.username, name: d.name, role: d.role, permissions: d.permissions
  }));
  return { ok: r.ok, role: d.role, perms: d.permissions };
})()

