(async () => {
  const sleep = ms => new Promise(r => setTimeout(r, ms));
  const rowCount = () => document.querySelectorAll('.exc-table-wrap tbody tr').length;
  const setNative = (el, v) => {
    const set = Object.getOwnPropertyDescriptor(window.HTMLInputElement.prototype, 'value').set;
    set.call(el, v);
    el.dispatchEvent(new Event('input', { bubbles: true }));
  };
  const out = {};
  const input = document.querySelector('.exc-search__input');

  out.rowsBefore = rowCount();
  setNative(input, 'Tan Boon');
  await sleep(300);
  out.rowsAfterSearch = rowCount();
  out.filterbar = document.querySelector('.exc-filterbar')?.textContent.trim() || null;

  setNative(input, 'zzzznomatch');
  await sleep(300);
  out.emptyStateText = document.querySelector('.exc-state')?.textContent.trim() || null;

  setNative(input, '');
  await sleep(300);
  out.rowsAfterClear = rowCount();
  return out;
})()

(async () => {
  const sleep = ms => new Promise(r => setTimeout(r, ms));
  const rows = () => [...document.querySelectorAll('.exc-table-wrap tbody tr')];
  const btn = document.querySelector('.exc-table-wrap .exc-btn-sm.escalate');
  if (!btn) return 'no escalate button';
  const row = btn.closest('tr');
  const before = { priority: row.querySelectorAll('td')[1]?.textContent, delegate: row.querySelectorAll('td')[3]?.textContent };
  btn.click();
  await sleep(2000);
  const after = rows().find(r => r.querySelectorAll('td')[3]?.textContent === before.delegate);
  return {
    before,
    afterPriority: after?.querySelectorAll('td')[1]?.textContent,
    stillHasEscalateBtn: after ? !!after.querySelector('.exc-btn-sm.escalate') : 'gone',
    criticalOpenTile: [...document.querySelectorAll('.exc-stat')].find(e=>/Critical open/.test(e.textContent))?.querySelector('.exc-stat__value')?.textContent,
    bannerText: document.querySelector('.exc-banner__title')?.textContent || null,
  };
})()

