(async () => {
  const sleep = ms => new Promise(r => setTimeout(r, ms));
  let captured = null, capturedName = null;
  const origCreate = URL.createObjectURL;
  const origClick = HTMLAnchorElement.prototype.click;
  URL.createObjectURL = (blob) => { captured = blob; return 'blob:stub'; };
  HTMLAnchorElement.prototype.click = function () { capturedName = this.download; };
  try {
    const btn = [...document.querySelectorAll('button')].find(b => /Export/.test(b.textContent));
    btn.click();
    await sleep(500);
    const text = captured ? await captured.text() : null;
    const lines = text ? text.split('\r\n') : [];
    return {
      filename: capturedName,
      mime: captured?.type,
      hasBom: text ? text.charCodeAt(0) === 0xFEFF : null,
      header: lines[0],
      rowCount: lines.length - 1,
      sampleRow: lines[1],
    };
  } finally {
    URL.createObjectURL = origCreate;
    HTMLAnchorElement.prototype.click = origClick;
  }
})()

(async () => {
  let captured = null;
  const origCreate = URL.createObjectURL;
  const origClick = HTMLAnchorElement.prototype.click;
  URL.createObjectURL = (b) => { captured = b; return 'blob:stub'; };
  HTMLAnchorElement.prototype.click = function () {};
  try {
    [...document.querySelectorAll('button')].find(b => /Export/.test(b.textContent)).click();
    await new Promise(r => setTimeout(r, 400));
    const buf = new Uint8Array(await captured.arrayBuffer());
    return {
      firstThreeBytes: [buf[0], buf[1], buf[2]],
      isUtf8Bom: buf[0] === 0xEF && buf[1] === 0xBB && buf[2] === 0xBF,
    };
  } finally { URL.createObjectURL = origCreate; HTMLAnchorElement.prototype.click = origClick; }
})()

