/* ---- Delegate status vocabulary ----------------------------------------- *
 * Two status models exist in the codebase at once:
 *
 *   this build   PRESENT | MISSING | UNASSIGNED
 *   JQ's build   UNASSIGNED | ASSIGNED | ARRIVED | LATE | MISSING
 *
 * ARRIVED is simply JQ's rename of PRESENT — his db/delegates.js normalize()
 * rewrites an incoming "PRESENT" to "ARRIVED", and his dashboard counts both
 * (isBoarded = PRESENT || ARRIVED). PRESENT is therefore still valid in BOTH
 * builds, while ARRIVED is only understood by his.
 *
 * So these screens READ the full five-status vocabulary — a delegate touched by
 * his build can come back ARRIVED or LATE, and must still render sensibly and
 * gate the Override action correctly — but keep WRITING PRESENT, the one value
 * every head-count in this build (data.js, vance.js, vimal.js) recognises.
 * Switching the writes to ARRIVED would silently drop those delegates out of
 * the dashboard until every one of those files is updated too.
 * -------------------------------------------------------------------------- */

/** Statuses that mean "checked in", across both models. */
export const CHECKED_IN_STATUSES = ["PRESENT", "ARRIVED"];

/** True when the delegate is already counted as boarded, in either model. */
export function isCheckedIn(status) {
  return CHECKED_IN_STATUSES.includes(status);
}

/** Display labels for every status either build can produce. */
export const STATUS_LABEL = {
  PRESENT: "Present",
  ARRIVED: "Arrived",
  LATE: "Late",
  ASSIGNED: "Assigned",
  MISSING: "Missing",
  UNASSIGNED: "Unassigned",
};

/** Human label for any delegate status, falling back to the raw value. */
export function statusLabel(status) {
  return STATUS_LABEL[status] || status || "—";
}

