.mexc-live .dot { width: 6px; height: 6px; border-radius: 50%; background: currentColor; }
`;

export default function MobileExceptionsPage() {
  const { t } = useLang();
  const canEdit = getPermissions().manageExceptions;

  const [tab, setTab] = useState("Open"); // phones default to what needs action
  const [allTickets, setAllTickets] = useState([]);
  const [counts, setCounts] = useState({ all: 0, critical: 0, open: 0, resolved: 0, criticalOpen: 0 });
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState("");
  const [live, setLive] = useState(false);
  const [query, setQuery] = useState("");
  const [busyId, setBusyId] = useState(null);
  const [modalOpen, setModalOpen] = useState(false);
  const [toast, setToast] = useState("");
  const [now, setNow] = useState(() => Date.now());

  useEffect(() => {
    const id = setInterval(() => setNow(Date.now()), AGE_TICK_MS);
    return () => clearInterval(id);
  }, []);

  const load = useCallback(async () => {
    setError("");
    try {
      const { tickets, counts } = await listExceptions(); // sliced client-side, as on desktop
      setAllTickets(tickets);
      setCounts(counts);
    } catch (e) {
      setError(e.message || "Couldn't load tickets.");
    } finally {
      setLoading(false);
    }
  }, []);

  useEffect(() => { setLoading(true); load(); }, [load]);

  useEffect(() => {
    const off = subscribeStream((event) => {
      if (event === "stream:open")  { setLive(true);  return; }
      if (event === "stream:error") { setLive(false); return; }
      setLive(true);
      load();
      if (event === "exception:critical") flash("Critical alert pushed to all staff devices");
    });
    return off;
  }, [load]);

  function flash(msg) { setToast(msg); setTimeout(() => setToast(""), 2600); }

  async function act(id, fn, okMsg) {
    setBusyId(id);
    try {
      await fn();
      flash(okMsg);
      await load();
    } catch (e) {
      flash(e.code === "ALREADY_RESOLVED" ? "That ticket was already resolved" : (e.message || "Action failed"));
      await load();
    } finally {
      setBusyId(null);
    }
  }

  const byTab = useMemo(() => {
    const f = TABS.find((x) => x.key === tab).filter;
    return allTickets.filter(
      (x) => (!f.status || x.status === f.status) && (!f.priority || x.priority === f.priority)
    );
  }, [allTickets, tab]);

  const tickets = useMemo(() => {
    const q = query.trim().toLowerCase();
    if (!q) return byTab;
    return byTab.filter((x) =>
      [issueLabel(x), x.delegateName, x.coach, x.note, x.raisedBy, x.resolvedBy]
        .some((v) => (v || "").toLowerCase().includes(q))
    );
  }, [byTab, query]);

  const oldest = useMemo(() => {
    const open = allTickets.filter((x) => x.status === "OPEN");
    return open.reduce((max, x) => Math.max(max, ageMinutes(x.createdAt, now) ?? 0), 0);
  }, [allTickets, now]);

  const critical = allTickets.find((x) => x.priority === "CRITICAL" && x.status === "OPEN");

  return (
    <div>
      <style>{MEXC_CSS}</style>

      <div className="row between" style={{ marginBottom: 12, alignItems: "flex-start" }}>
        <div>
          <div style={{ fontSize: 12, fontWeight: 600, letterSpacing: "0.06em", textTransform: "uppercase", color: "var(--ink-3)" }}>
            {t("Beijing study mission")}
          </div>
          <h1 style={{ fontSize: 22, margin: "4px 0 0" }}>{t("Exceptions")}</h1>
        </div>
        <div className="row" style={{ gap: 8, alignItems: "center" }}>
          <span className={"mexc-live" + (live ? "" : " off")}><span className="dot" /> {live ? t("Live") : t("…")}</span>
          <button className="btn btn-ghost" onClick={load} aria-label={t("Refresh")} style={{ padding: 8 }}>
            <RefreshCw size={16} className={loading ? "mexc-spin" : ""} />
          </button>
        </div>
      </div>

      <div className="mexc-stats">
        <div className="mexc-stat">
          <div className="mexc-stat__label">{t("Open")}</div>
          <div className="mexc-stat__value">{counts.open ?? 0}</div>
        </div>
        <div className={"mexc-stat" + ((counts.criticalOpen ?? 0) > 0 ? " danger" : "")}>
          <div className="mexc-stat__label">{t("Critical")}</div>
          <div className="mexc-stat__value">{counts.criticalOpen ?? 0}</div>
        </div>
        <div className={"mexc-stat" + (oldest >= 30 ? " danger" : oldest >= 15 ? " warn" : "")}>
          <div className="mexc-stat__label">{t("Oldest")}</div>
          <div className="mexc-stat__value">{counts.open ? fmtAge(oldest) : "—"}</div>
        </div>
      </div>

      {critical && (
        <div className="mexc-banner">
          <AlertTriangle size={18} color="var(--scc-red)" strokeWidth={2.2} style={{ flexShrink: 0, marginTop: 1 }} />
          <div style={{ minWidth: 0 }}>
            <div className="mexc-banner__title">
              {counts.criticalOpen} {t("critical open")} · {t("pushed to all staff")}
            </div>
            <div className="mexc-banner__sub">
              {issueLabel(critical)} · {critical.delegateName || t("Unidentified")} · {fmtTime(critical.createdAt)}
            </div>
          </div>
        </div>
      )}

      <div className="mexc-tabs" role="tablist">
        {TABS.map(({ key, countKey }) => (
          <button key={key} role="tab" aria-selected={tab === key}
            className={"mexc-tab" + (tab === key ? " active" : "")} onClick={() => setTab(key)}>
            {t(key)} <span className="count">· {counts[countKey] ?? 0}</span>
          </button>
        ))}
      </div>

      <div className="mexc-search">
        <Search size={15} />
        <input value={query} onChange={(e) => setQuery(e.target.value)}
               placeholder={t("Search delegate, coach, issue…")} aria-label={t("Search tickets")} />
        {query && <button onClick={() => setQuery("")} aria-label={t("Clear search")}><X size={14} /></button>}
      </div>

      {error && (
        <div className="mobile-card" style={{ borderColor: "var(--st-missing)", background: "var(--st-missing-bg)" }}>
          <div className="row" style={{ gap: 8, color: "var(--st-missing)", fontWeight: 600, fontSize: 14 }}>
            <AlertTriangle size={16} /> {t("Couldn't reach the backend")}
          </div>
          <p className="muted" style={{ fontSize: 12, marginTop: 4 }}>{error}</p>
          <button className="mexc-btn" style={{ marginTop: 10 }} onClick={load}>{t("Retry")}</button>
        </div>
      )}

      {loading && !allTickets.length && !error && <div className="muted">{t("Loading…")}</div>}

      {!loading && !error && tickets.length === 0 && (
        <div className="mexc-empty">
          {query ? `${t("No tickets match")} “${query}”.` : t("All clear — nothing in this view.")}
        </div>
      )}

      {!error && tickets.map((x) => {
        const lvl = ageLevel(x, now);
        const present = isCheckedIn(x.delegateStatus);
        const busy = busyId === x.id;
        return (
          <div key={x.id} className={"mexc-card" + (x.priority === "CRITICAL" && x.status === "OPEN" ? " crit" : "")}>
            <div className="mexc-card__top">
              <StatusBadge state={x.priority} />
              <StatusBadge state={x.status} />
            </div>

            <div className="mexc-title">
              {issueLabel(x)}
              {x.delegateVip && <span className="mexc-vip">VIP</span>}
            </div>
            {x.note && <div className="mexc-note">{x.note}</div>}
            <div className="mexc-meta">{x.delegateName || t("Unidentified")} · {x.coach || "—"}</div>
            <div className="mexc-meta">{fmtTime(x.createdAt)} · {x.raisedBy}</div>

            {x.status === "OPEN" && (
              <span className={"mexc-age" + (lvl ? " " + lvl : "")}>
                <Clock size={11} /> {fmtAge(ageMinutes(x.createdAt, now))}
              </span>
            )}
            {x.status === "RESOLVED" && x.resolvedAt && (
              <span className="mexc-resolved">
                {t("resolved")} {fmtTime(x.resolvedAt)}
                {x.resolvedBy ? ` · ${x.resolvedBy}` : ""}
                {resolveMinutes(x) != null ? ` · ${t("took")} ${fmtAge(resolveMinutes(x))}` : ""}
              </span>
            )}

            {canEdit && (
              <div className="mexc-actions">
                {x.status === "OPEN" && (
                  <>
                    <button className="mexc-btn resolve" disabled={busy}
                      onClick={() => act(x.id, () => resolveException(x.id), "Ticket resolved")}>
                      <CheckCircle2 size={14} /> {t("Resolve")}
                    </button>
                    {x.priority !== "CRITICAL" && (
                      <button className="mexc-btn escalate" disabled={busy}
                        onClick={() => act(x.id, () => updatePriority(x.id, "CRITICAL"), "Escalated — alert pushed to all staff")}>
                        <ChevronsUp size={14} /> {t("Escalate")}
                      </button>
                    )}
                    {x.delegateId && !present && (
                      <button className="mexc-btn" disabled={busy}
                        onClick={() => act(x.id, () => manualOverride(x.delegateId), `${x.delegateName} marked present`)}>
                        <UserCheck size={14} /> {t("Override")}
                      </button>
                    )}
                    {x.delegateId && present && (
                      <span className="mexc-present"><CheckCircle2 size={14} /> {t("Present")}</span>
                    )}
                  </>
                )}
                <button className="mexc-btn danger" disabled={busy} aria-label={t("Delete")}
                  onClick={() => act(x.id, () => deleteException(x.id), "Ticket deleted")}>
                  <Trash2 size={14} />
                </button>
              </div>
            )}
          </div>
        );
      })}

      {canEdit && (
        <button className="btn btn-primary mexc-fab" onClick={() => setModalOpen(true)}>
          <Plus size={16} strokeWidth={2.5} /> {t("Log exception")}
        </button>
      )}

      {modalOpen && (
        <LogExceptionModal
          onClose={() => setModalOpen(false)}
          onCreated={(_t, wasCritical) => {
            setModalOpen(false);
            flash(wasCritical ? "Critical alert pushed to all staff devices" : "Exception logged");
            load();
          }}
        />
      )}

      {toast && <div className="mexc-toast">{toast}</div>}
      <style>{`.mexc-spin{animation:mexc-rot .9s linear infinite}@keyframes mexc-rot{to{transform:rotate(360deg)}}`}</style>
    </div>
  );
}

