  out.actionButtons = [...card.querySelectorAll('.mexc-btn')].map(b => b.textContent.trim() || b.getAttribute('aria-label'));
  out.presentTag = card.querySelector('.mexc-present')?.textContent.trim() || null;
  out.agePill = card.querySelector('.mexc-age')?.textContent.trim() + ' | ' + card.querySelector('.mexc-age')?.className;
  // does the "Exceptions" label clip or wrap?
  const exTab = [...document.querySelectorAll('.mobile-tab')].find(a => /Exceptions/.test(a.textContent));
  const span = exTab.childNodes[exTab.childNodes.length - 1];
  const r = exTab.getBoundingClientRect();
  out.tabLabel = { text: exTab.textContent.trim(), boxW: Math.round(r.width), scrollW: exTab.scrollWidth, clipped: exTab.scrollWidth > Math.ceil(r.width) + 1, lines: Math.round(r.height) };
  // all action buttons fit within card?
  const cr = card.getBoundingClientRect();
  out.buttonsOverflowCard = [...card.querySelectorAll('.mexc-btn')].some(b => b.getBoundingClientRect().right > cr.right + 1);
  return out;
})()

