(async () => {
  const [{ default: StatusBadge }, api, React, { createRoot }] = await Promise.all([
    import('/src/components/StatusBadge.jsx'),
    import('/src/lib/exceptionsApi.js'),
    import('react'),
    import('react-dom/client'),
  ]);
  // render each status through the real StatusBadge
  const host = document.createElement('div');
  document.body.appendChild(host);
  const root = createRoot(host);
  const states = ['PRESENT','ARRIVED','LATE','ASSIGNED','MISSING','UNASSIGNED'];
  root.render(React.createElement('div', null, states.map(s =>
    React.createElement('span', { key: s, 'data-s': s }, React.createElement(StatusBadge, { state: s })))));
  await new Promise(r => setTimeout(r, 400));
  const rendered = states.map(s => {
    const el = host.querySelector(`[data-s="${s}"] .badge`);
    return `${s} -> "${el?.textContent}" [${el?.className.replace('badge ','')}]`;
  });
  root.unmount(); host.remove();
  return {
    badges: rendered,
    isCheckedIn: states.map(s => `${s}: ${api.isCheckedIn(s)}`),
    statusLabels: states.map(s => `${s}: ${api.statusLabel(s)}`),
  };
})()

