(async () => {
  // capture any error thrown on a fresh mount of the page
  const errs = [];
  const onErr = (e) => errs.push(String(e.error?.message || e.message));
  const onRej = (e) => errs.push('unhandled: ' + String(e.reason?.message || e.reason));
  window.addEventListener('error', onErr);
  window.addEventListener('unhandledrejection', onRej);
  const origErr = console.error;
  console.error = (...a) => { errs.push(a.map(x => String(x?.message || x)).join(' ').slice(0,300)); origErr(...a); };
  // force a remount by navigating away and back within the SPA
  history.pushState({}, '', '/dashboard');
  window.dispatchEvent(new PopStateEvent('popstate'));
  await new Promise(r => setTimeout(r, 900));
  history.pushState({}, '', '/exceptions');
  window.dispatchEvent(new PopStateEvent('popstate'));
  await new Promise(r => setTimeout(r, 2000));
  console.error = origErr;
  window.removeEventListener('error', onErr);
  window.removeEventListener('unhandledrejection', onRej);
  return { errors: errs.slice(0, 6), stillRenders: !!document.querySelector('.page-title'), rows: document.querySelectorAll('.exc-table-wrap tbody tr').length };
})()

