  border-radius: var(--r-sm); padding: 0 10px; height: 38px; color: var(--ink-3);
}
.exc-search:focus-within { border-color: var(--ink-3); }
.exc-search__input {
  border: none; outline: none; background: none; font-size: 14px;
  color: var(--ink); width: 208px; max-width: 46vw; padding: 0;
}
.exc-search__x { border: none; background: none; color: var(--ink-3); display: inline-flex; padding: 2px; border-radius: 4px; }
.exc-search__x:hover { background: var(--surface-2); }

/* Result count when a search is narrowing the tab */
.exc-filterbar {
  display: flex; align-items: center; justify-content: space-between; gap: 12px;
  font-size: 13px; color: var(--ink-3); margin: -6px 0 14px;
}

/* ---- Bulk action bar ---------------------------------------------------- */
.exc-bulkbar {
  display: flex; align-items: center; justify-content: space-between; gap: 12px;
  padding: 10px 16px; margin-bottom: 14px;
  background: var(--st-normal-bg); border: 1px solid var(--st-normal);
  border-radius: var(--r-md); font-size: 14px; color: var(--ink-2);
}
.exc-checkcol { width: 36px; text-align: center; }
.exc-checkcol input { width: 15px; height: 15px; accent-color: var(--scc-red); cursor: pointer; }
.exc-row-sel > td { background: var(--st-normal-bg); }

/* ---- Ageing + resolution meta ------------------------------------------- */
.exc-age {
  display: inline-flex; align-items: center; gap: 4px; margin-top: 3px;
  font-size: 11.5px; font-weight: 600; color: var(--ink-3);
  background: var(--st-neutral-bg); padding: 2px 7px; border-radius: 999px;
  font-variant-numeric: tabular-nums;
}
.exc-age.warn { color: var(--st-review);  background: var(--st-review-bg); }
.exc-age.late { color: var(--scc-red);    background: var(--scc-red-tint); }
.exc-resolved-meta { display: block; margin-top: 3px; font-size: 11.5px; color: var(--st-present); }

/* ---- Row actions -------------------------------------------------------- */
.exc-actions { display: flex; gap: 8px; justify-content: flex-end; align-items: center; flex-wrap: wrap; }
.exc-present-tag {
  display: inline-flex; align-items: center; gap: 5px;
  font-size: 12.5px; font-weight: 600; color: var(--st-present);
  background: var(--st-present-bg); padding: 5px 10px; border-radius: var(--r-sm);
}

