describe("fmtAge — compact human age", () => {
  test("under a minute reads 'just now'", () => {
    assert.equal(fmtAge(0), "just now");
  });

  test("under an hour is plain minutes", () => {
    assert.equal(fmtAge(1), "1m");
    assert.equal(fmtAge(59), "59m");
