/**
 * Copy Claude Code session logs into the repo with secrets stripped IN FLIGHT,
 * so an unredacted copy is never written to disk inside the repository.
 *
 * Covers the patterns named in MusterGo_TEAM_SUBMISSION_GUIDE.md plus the
 * specific literal values known to appear in this project's shared .env.
 */
import { readFileSync, writeFileSync, mkdirSync, readdirSync } from "node:fs";
import { join, basename } from "node:path";

const SRC = process.argv[2];
const DEST = process.argv[3];
mkdirSync(DEST, { recursive: true });

// Ordered: generic patterns first, then the exact literals as a backstop.
const RULES = [
  // SendGrid API keys (SG.<id>.<secret>)
  [/SG\.[A-Za-z0-9_-]{16,}\.[A-Za-z0-9_-]{16,}/g, "[REDACTED]"],
  [/SG\.[A-Za-z0-9_.-]{20,}/g, "[REDACTED]"],
  // KEY=value for the sensitive env keys
  [/(SMTP_PASS|JWT_SECRET|CLOUDINARY_API_SECRET|CLOUDINARY_API_KEY|ANTHROPIC_API_KEY|DATABASE_URL)=([^"\\ ,\n]{6,})/g,
    (_m, k) => `${k}=[REDACTED]`],
  // password inside any connection string  scheme://user:pass@host
  [/(:\/\/[^:@/\s"]+:)[^@"\s]{6,}@/g, "$1[REDACTED]@"],
  // Anthropic-style keys, just in case
  [/sk-ant-[A-Za-z0-9_-]{20,}/g, "[REDACTED]"],
  // Exact literals from this project's shared .env (backstop)
  [/[REDACTED]/g, "[REDACTED]"],
  [/[REDACTED]/g, "[REDACTED]"],
  [/[REDACTED]/g, "[REDACTED]"],
  [/[REDACTED]/g, "[REDACTED]"],
  [/[REDACTED]/g, "[REDACTED]"],
];

// Anything still matching these after redaction is a failure.
const VERIFY = [
  ["sendgrid key", /SG\.[A-Za-z0-9_-]{16,}\.[A-Za-z0-9_-]{16,}/],
  ["neon db password", /[REDACTED]/],
  ["cloudinary secret", /[REDACTED]/],
  ["cloudinary key", /[REDACTED]/],
  ["jwt secret", /[REDACTED]/],
];

let totalRedactions = 0;
const files = readdirSync(SRC).filter((f) => f.endsWith(".jsonl"));

for (const f of files) {
  const before = readFileSync(join(SRC, f), "utf8");
  let after = before;
  for (const [re, rep] of RULES) after = after.replace(re, rep);

  const n = (after.match(/\[REDACTED\]/g) || []).length -
            (before.match(/\[REDACTED\]/g) || []).length;
  totalRedactions += n;

  // JSONL integrity: every non-empty line must still parse as JSON.
  const lines = after.split("\n").filter((l) => l.trim());
  let bad = 0;
  for (const l of lines) { try { JSON.parse(l); } catch { bad += 1; } }

  writeFileSync(join(DEST, basename(f)), after);
  console.log(`  ${f}: ${n} redactions, ${lines.length} lines, ${bad} unparseable`);
}

console.log(`\n  total redactions: ${totalRedactions}`);
console.log("  --- verification on WRITTEN files ---");
let clean = true;
for (const f of files) {
  const out = readFileSync(join(DEST, f), "utf8");
  for (const [label, re] of VERIFY) {
    if (re.test(out)) { console.log(`  !! ${f}: ${label} STILL PRESENT`); clean = false; }
  }
}
console.log(clean ? "  ALL CLEAN — no known secret survives" : "  FAILED — secrets remain");

