/**
 * Independent, exhaustive secret-leak check. Does NOT reuse the redactor's own
 * rules or self-report — it slides an 8-char window across each full known
 * secret and greps the WRITTEN output file for every substring, so a partial
 * fragment typed anywhere in the source transcript (e.g. while diagnosing)
 * cannot hide from a rule that only matched the full string.
 */
import { readFileSync } from "node:fs";

const SECRETS = {
  "Neon DB password": "[REDACTED]",
  "Cloudinary secret": "[REDACTED]",
  "Cloudinary key": "[REDACTED]",
  "JWT secret": "[REDACTED]",
  "SendGrid key": "[REDACTED]",
};

const WINDOW = 8;
const files = process.argv.slice(2);
let anyLeak = false;

for (const file of files) {
  console.log(`\n=== ${file} ===`);
  const text = readFileSync(file, "utf8");
  let fileClean = true;

  for (const [label, secret] of Object.entries(SECRETS)) {
    const hits = new Set();
    for (let i = 0; i + WINDOW <= secret.length; i++) {
      const chunk = secret.slice(i, i + WINDOW);
      if (text.includes(chunk)) hits.add(chunk);
    }
    if (hits.size) {
      console.log(`  !! ${label}: ${hits.size} distinct ${WINDOW}-char fragment(s) found: ${[...hits].join(", ")}`);
      fileClean = false;
      anyLeak = true;
    }
  }
  console.log(fileClean ? "  ALL 5 SECRETS: no 8-char fragment survives" : "  LEAK DETECTED");
}

console.log(anyLeak ? "\n>>> OVERALL: FAILED" : "\n>>> OVERALL: CLEAN");
process.exit(anyLeak ? 1 : 0);

